INSERT INTO public.artikel (id, title, category, date, datetime, image, excerpt, content, author) VALUES
(5, 'Mengenal Dunia Kerja Digital Banking, Himsika Gelar Information System Company Tour 2026 ke Menara blu', 'Berita', '26 September 2026', '2026-09-26', '', 'JAKARTA — Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang (Himsika) kembali menyelenggarakan salah satu program kerja strategisnya, yaitu Information System Company Tour (ISCT) 2026, pada Rabu,…', '[{"type":"gallery","images":[{"src":"","alt":"Salinan IMG_9701"},{"src":"","alt":"Salinan IMG_9442"},{"src":"","alt":"Salinan IMG_9556"},{"src":"","alt":"Salinan IMG_9534"},{"src":"","alt":"Salinan IMG_9705"},{"src":"","alt":"IMG_9664"},{"src":"","alt":"IMG_9513"},{"src":"","alt":"IMG_9663"},{"src":"","alt":"IMG_9394"},{"src":"","alt":"IMG_9670"},{"src":"","alt":"IMG_9694"},{"src":"","alt":"IMG_9714"},{"src":"","alt":"IMG_9448"},{"src":"","alt":"IMG_9672"}]},{"type":"paragraph","text":"<b>JAKARTA</b> — Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang (Himsika) kembali menyelenggarakan salah satu program kerja strategisnya, yaitu <b>Information System Company Tour (ISCT) 2026</b>, pada Rabu, 24 Juni 2026. Kegiatan kunjungan industri ini bertujuan untuk memberikan gambaran secara langsung mengenai iklim kerja profesional, tata kelola teknologi, serta penerapan ilmu sistem informasi di dunia industri nyata."},{"type":"paragraph","text":"Pada edisi tahun ini, Himsika berkesempatan mengunjungi kantor pusat <b>blu by BCA Digital</b> yang berlokasi di Menara blu, Jakarta Pusat. Sebanyak 36 mahasiswa aktif Sistem Informasi angkatan 2023 hingga 2025 berpartisipasi penuh antusias hingga seluruh kuota yang disediakan terisi penuh."},{"type":"heading","text":"Eksplorasi Profil Bisnis dan Keamanan Siber"},{"type":"paragraph","text":"Rangkaian acara diawali dengan sambutan hangat dan pembukaan resmi dari pihak manajerial BCA Digital serta perwakilan pengurus Himsika. Acara kemudian dilanjutkan dengan pemutaran video <i>company profile</i> untuk mengenalkan rekam jejak, budaya kerja, serta inovasi perbankan digital yang dikembangkan oleh blu. Suasana semakin interaktif saat memasuki sesi kuis, di mana para mahasiswa berkesempatan menjawab pertanyaan seputar materi yang ditayangkan dan mendapatkan apresiasi menarik langsung dari pihak blu."},{"type":"paragraph","text":"Memasuki agenda inti, para peserta dibekali paparan materi mendalam yang terbagi ke dalam dua sesi:"},{"type":"list","ordered":true,"items":["Profil Bisnis & Operasional blu (<i>Inside & Outside BCA Digital</i>): Membedah arsitektur bisnis perbankan digital, integrasi layanan finansial berbasis aplikasi, serta peran penting sistem informasi dalam mendukung ekosistem digital.","Keamanan Siber (<i>Enterprise Security</i>): Membahas strategi perlindungan data, mitigasi risiko siber, dan standar keamanan infrastruktur teknologi perbankan modern."]},{"type":"heading","text":"Office Tour dan Penyerahan Cendera Mata"},{"type":"paragraph","text":"Usai sesi materi dan tanya jawab yang dinamis, para peserta diajak berkeliling (<i>office tour</i>) untuk melihat secara langsung lingkungan kerja modern di Menara blu serta mengeksplorasi fasilitas area perkantoran. Rangkaian acara diisi pula dengan sesi ramah tamah (<i>free time</i>) yang memberikan ruang bagi mahasiswa untuk berdiskusi dan memperluas jaringan."},{"type":"paragraph","text":"<i>[Gambar 1. Penyerahan sertifikat Ketua Pelaksana ISCT kepada pihak Blu]</i>"},{"type":"paragraph","text":"Kegiatan formal di Menara blu ditutup dengan penyerahan sertifikat dan plakat kenang-kenangan oleh Ketua Pelaksana ISCT 2026 kepada perwakilan pimpinan BCA Digital sebagai simbol apresiasi dan kerja sama. Sebelum bertolak kembali ke Karawang, seluruh rangkaian acara diakhiri dengan agenda <i>free time</i> bagi para peserta di kawasan Thamrin City, Jakarta Pusat."},{"type":"paragraph","text":"[Gambar 2. Dokumentasi bersama perwakilan pihak Blu]"},{"type":"paragraph","text":"Melalui penyelenggaraan ISCT 2026 ini, Himsika berharap para mahasiswa dapat memperoleh wawasan praktis, memotivasi kesiapan karir di bidang perbankan digital dan teknologi informasi, serta memperkuat hubungan sinergis antara akademisi dan dunia industri."}]'::jsonb, 'HIMSIKA'),
(6, 'Sajikan Seminar, Pameran, dan Kompetisi Nasional: Himsika Sukses Gelar Rangkaian Megah Education Fair 2026', 'Berita', '26 September 2026', '2026-09-26', '', 'KARAWANG — Himpunan Mahasiswa Sistem Informasi (Himsika) sukses menyelenggarakan seluruh rangkaian kegiatan Education Fair (Edufair) 2026. Mengusung tema besar “Transforming Digital Business with Generative AI: From…', '[{"type":"gallery","images":[{"src":"","alt":"IMG_20260525_140806"},{"src":"","alt":"DSCF6284"},{"src":"","alt":"DSCF6346"},{"src":"","alt":"DSCF5870"},{"src":"","alt":"IMG_20260525_140444"},{"src":"","alt":"DSCF6057"},{"src":"","alt":"IMG_20260525_185810"},{"src":"","alt":"DSCF6284"},{"src":"","alt":"DSCF6346"},{"src":"","alt":"DSCF5964"},{"src":"","alt":"DSCF6310"},{"src":"","alt":"DSCF6090"},{"src":"","alt":"DSCF6004"},{"src":"","alt":"DSCF5999"},{"src":"","alt":"IMG_1473"}]},{"type":"paragraph","text":"<b>KARAWANG</b> — Himpunan Mahasiswa Sistem Informasi (Himsika) sukses menyelenggarakan seluruh rangkaian kegiatan <b>Education Fair (Edufair) 2026</b>. Mengusung tema besar <i>“Transforming Digital Business with Generative AI: From Strategy to Hands-On Solution”</i> serta <i>“Creative Digital Entrepreneurship Through User-Centered Innovation”</i>, Edufair 2026 hadir sebagai wadah strategis untuk memperluas wawasan akademis, mengasah keterampilan praktis, hingga menguji inovasi digital mahasiswa dan pelajar di tingkat nasional."},{"type":"paragraph","text":"Rangkaian kegiatan Edufair 2026 terbagi ke dalam dua pilar utama, yaitu <b>Silogy Nexpo</b> sebagai pembuka acara secara luring dan <b>Silogy National Competition</b> sebagai pilar kompetisi nasional berbasis daring."},{"type":"heading","text":"1. Silogy Nexpo 2026: Edukasi dan Pameran Inovasi Digital"},{"type":"paragraph","text":"Rangkaian Edufair 2026 resmi dimulai melalui gelaran <b>Silogy Nexpo 2026</b> yang berlangsung meriah secara luring di Aula Husni Hamid, Komplek Pemda Karawang, pada Sabtu, 23 Mei 2026. Acara dibuka secara resmi melalui <i>Opening Ceremony</i> oleh Kepala Jurusan Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang, Bapak Carudin M.Kom., usai penyampaian laporan oleh Ketua Pelaksana."},{"type":"paragraph","text":"<i>[Gambar 1. Pembukaan Edufair oleh Kepala Jurusan]</i>"},{"type":"paragraph","text":"Silogy Nexpo menyajikan dua pilar kegiatan utama:"},{"type":"list","ordered":false,"items":["Seminar & Workshop Nasional: Menghadirkan sesi Seminar Nasional (<i>Strategic Transformation of Digital Business with Generative AI</i>) bersama Miftah Muhammad Farhan (<i>Senior Software Engineer & Frontend Developer</i> di Dibimbing) dan Fariz Rizky Rizaldy (<i>Software Developer</i> di SALT). Rangkaian dilanjutkan dengan Workshop Nasional (<i>Hands-On Generative AI for Digital Business Solutions</i>) bersama Emirsyah Rafsanjani (<i>Generative AI Mentor Trainee</i> di BlockDev) di mana peserta melakukan praktik langsung solusi bisnis berbasis AI.","Pameran Karya Digital (<i>Silogy Nexpo Exhibition</i>): Area pameran menampilkan puluhan karya digital inovatif mahasiswa, mulai dari proyek pengembangan <i>Website</i>, <i>Mobile Apps</i>, desain <i>UI/UX</i>, <i>Desain Grafis</i>, <i>Business Paper</i>, hingga solusi berbasis <i>Internet of Things (IoT)</i>."]},{"type":"heading","text":"2. Silogy National Competition 2026: Unjuk Gigi Talenta Digital Nasional"},{"type":"paragraph","text":"Sebagai puncak sekaligus penutup rangkaian Edufair 2026, Himsika menggelar Silogy National Competition 2026. Bertujuan menjaring talenta muda berbakat, kompetisi nasional ini diikuti oleh 65 tim pendaftar dari kategori pelajar SMA/SMK/MA hingga mahasiswa dari berbagai perguruan tinggi di Indonesia (47 pendaftar UI/UX Design dan 18 pendaftar Business Plan). Setelah melalui tahap seleksi karya yang ketat, 10 tim finalis terbaik berhak melaju ke babak puncak."},{"type":"paragraph","text":"<i>[Gambar 2. Penutupan Rangkaian Education Fair 2026]</i>"},{"type":"paragraph","text":"Babak Puncak/Final dilaksanakan secara <i>full online</i> melalui Zoom Meeting pada Selasa, 7 Juli 2026. Dimulai pukul 08.00 WIB dengan pembukaan dan pengondisian peserta, agenda berlanjut ke sesi presentasi karya di hadapan dewan juri dosen Fakultas Ilmu Komputer UNSIKA, yaitu Ade Andri Hendriadi, S.Si., M.Kom. dan Hannie, S.Kom., M.M.S.I. (Juri Business Plan), serta Garno, M.Kom. dan Aji Primajaya, S.Si., M.Kom. (Juri UI/UX Design)."},{"type":"paragraph","text":"Tepat pada pukul 11.45 WIB, diumumkan jajaran pemenang Silogy National Competition 2026:"},{"type":"paragraph","text":"<b>Kategori Business Plan:</b>"},{"type":"list","ordered":true,"items":["🥇 Juara 1: Tim Info Magang — Universitas Singaperbangsa Karawang","🥈 Juara 2: Tim Ngaduin AI — Sekolah Vokasi IPB University","🥉 Juara 3: Tim Trishara — Universitas Tidar"]},{"type":"paragraph","text":"<b>Kategori UI/UX Design:</b>"},{"type":"list","ordered":true,"items":["🥇 Juara 1: Tim Khalifah — Universitas Pendidikan Indonesia","🥈 Juara 2: Tim Karolina — Telkom University","🥉 Juara 3: Tim Ga Seriussss Jujur — Universitas Diponegoro"]},{"type":"heading","text":"Penutupan Resmi Rangkaian Edufair 2026"},{"type":"paragraph","text":"Seluruh rangkaian megah Education Fair 2026 secara resmi ditutup melalui <i>Closing Ceremony</i> oleh Koordinator Program Studi Sistem Informasi, Azhari Ali Ridha, S.Si., M.Kom."},{"type":"paragraph","text":"Pihak program studi mengapresiasi tinggi komitmen dan konsistensi Himsika dalam menyelenggarakan perhelatan akademis dan kompetisi yang inklusif serta berdampak luas. Melalui Edufair 2026, Himsika membuktikan perannya dalam mendorong lahirnya generasi muda yang adaptif, inovatif, serta siap memimpin transformasi bisnis dan teknologi digital di Indonesia."}]'::jsonb, 'HIMSIKA'),
(1, 'Pererat Hubungan dan Berbagi Inovasi, HIMSIKA UNSIKA Gelar Studi Banding "Make Connection × Standing" Bersama HIMATIF UNPAD', 'Kegiatan', '09 Mei 2026', '2026-05-09', '', 'HIMSIKA UNSIKA sukses menyelenggarakan kolaborasi "Make Connection × Standing" bersama HIMATIF UNPAD sebagai upaya mempererat relasi dan berbagi inspirasi.', '[{"type":"paragraph","text":"<strong>JATINANGOR</strong>  — Dalam upaya memperluas cakrawala organisasi dan membangun jejaring akademis yang kuat, Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang sukses menyelenggarakan salah satu program kerja unggulannya, \"Make Connection × Standing\". Pada kesempatan kali ini, kegiatan tersebut dilaksanakan melalui kolaborasi sinergis dengan program kerja milik Himpunan Mahasiswa Teknik Informatika (Himatif Unpad) yang bernama \"Standing\". Kolaborasi dua program kerja ini mengusung tajuk resmi \"Make Connection × Standing\" dengan tema kegiatan “Menjalin Relasi, Berbagi Inspirasi untuk Organisasi yang Berkualitas” dan berlangsung pada Sabtu, 9 Mei 2026."},{"type":"paragraph","text":"Bertempat di Gedung Fakultas Matematika dan Ilmu Pengetahuan Alam (FMIPA) Unpad, Jatinangor, pertemuan antara dua himpunan berbasis teknologi informasi ini berlangsung dengan hangat, interaktif, dan penuh semangat kolaboratif."},{"type":"heading","text":"Sinergi Profil Organisasi dan Pertukaran Ide"},{"type":"paragraph","text":"Rangkaian acara \"Make Connection x Standing\" diawali dengan sesi pembukaan formal yang kemudian dilanjutkan dengan pemaparan profil masing-masing himpunan. Melalui sesi ini, baik Himsika maupun Himatif berkesempatan untuk mengenalkan visi, misi, struktur kepengurusan, serta program kerja unggulan yang menjadi fokus utama dalam periode kepengurusan masing-masing. Pemaparan ini membuka ruang diskusi awal mengenai perbedaan dan persamaan tantangan struktural yang dihadapi oleh kedua himpunan tersebut."},{"type":"image","image":"","alt":"Foto bersama Ketua Pelaksana","caption":"[Gambar 1. Foto bersama Ketua Pelaksana Make Connection & Ketua Himatif]"},{"type":"paragraph","text":"Setelah pengenalan struktural secara makro, agenda berlanjut ke inti kolaborasi, yaitu Focus Group Discussion (FGD). Dalam sesi FGD ini, para pengurus dari kedua himpunan dibagi ke dalam beberapa kelompok berdasarkan bidang kerja atau divisi yang setara (seperti divisi internal, eksternal, pengembangan sumber daya mahasiswa, hingga riset dan teknologi)."},{"type":"paragraph","text":"<br />Sesi diskusi kelompok ini berlangsung interaktif, di mana masing-masing himpunan saling bertukar pikiran mengenai efektivitas program kerja, pengelolaan konflik internal, hingga strategi adaptasi organisasi mahasiswa di tengah perkembangan teknologi yang dinamis."},{"type":"image","image":"","alt":"Suasana Diskusi FGD","caption":"Gambar 2. Sesi Focus Group Discussion (FGD) yang berlangsung interaktif"},{"type":"heading","text":"Mempererat Keakraban di Kampus Jatinangor"},{"type":"paragraph","text":"Setelah diskusi yang cukup mendalam dan produktif, rangkaian kegiatan ditutup dengan agenda yang lebih santai dan rekreatif, yaitu Campus Tour dimana kami mengelilingi kampus Unpad dipandu oleh teman-teman Himatif. Sembari menikmati suasana asri Jatinangor, momen ini dimanfaatkan oleh para peserta untuk saling berbincang secara informal, mempererat kedekatan personal, dan memperluas jaringan pertemanan antar-mahasiswa."},{"type":"paragraph","text":"<br />Kegiatan studi banding kolaboratif ini diakhiri dengan penyerahan plakat kenang-kenangan sebagai simbol dimulainya hubungan baik antara kedua belah pihak, diikuti dengan sesi foto bersama seluruh fungsionaris yang hadir."},{"type":"image","image":"","alt":"Sesi foto bersama","caption":"Gambar 3. Sesi foto bersama HIMSIKA UNSIKA × HIMATIF UNPAD"},{"type":"paragraph","text":"Melalui kolaborasi \"Make Connection × Standing\" ini, Himsika Unsika tidak hanya membawa pulang perspektif baru dalam pengelolaan organisasi, tetapi juga berhasil meletakkan batu pertama bagi potensi kolaborasi akademis maupun non-akademis dengan Himatif Unpad di masa yang akan datang."}]'::jsonb, 'HIMSIKA'),
(7, 'Revoist 5.0  “Symphony in Celebration of Light, Laughs, and Legacy”', 'Berita', '18 November 2025', '2025-11-18', '', '“Symphony in Celebration of Light, Laughs, and Legacy”', '[{"type":"gallery","images":[{"src":"","alt":"2013_0101_22054500"},{"src":"","alt":"2013_0101_22104900"},{"src":"","alt":"2013_0101_23080800"},{"src":"","alt":"2013_0102_03442500"},{"src":"","alt":"2013_0102_00354800"},{"src":"","alt":"IMG_0268"},{"src":"","alt":"IMG_0051"},{"src":"","alt":"IMG_0060"},{"src":"","alt":"IMG_0560"}]},{"type":"paragraph","text":"<i>“Symphony in Celebration of Light, Laughs, and Legacy”</i>"},{"type":"paragraph","text":"Pada hari Minggu, 09 November 2025, Himpunan Mahasiswa Sistem Informasi Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang sukses menyelenggarakan Revoist 5.0. Kegiatan ini mengusung tema <i>“Symphony in Celebration of Light, Laughs, and Legacy” </i>yang bermakna dapat mencerminkan semangat dan energi yang membara dalam setiap individu yang menjadi bagian dari organisasi Himpunan Mahasiswa Sistem Informasi Unsika. Api melambangkan kekuatan, keberanian, dan tekad yang tidak pernah padam, bahkan ketika menghadapi tantangan dan rintangan yang berat."},{"type":"heading","text":"Tujuan dan Bentuk Kegiatan"},{"type":"paragraph","text":"Revoist 5.0 ini bertujuan untuk memperingati hari lahirnya Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang tahun 2025, mempererat hubungan kekerabatan keluarga besar Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang dan memperkuat rasa cinta terhadap himpunannya sendiri."},{"type":"paragraph","text":"Acara ini mempunyai berbagai kegiatan seperti acara simbolis bertambahnya usia Himsika dengan pemotongan tumpeng, serta diisi dengan kegiatan hiburan lainnya seperti penampilan UKF seni tari, penampilan kelas, photobooth, Revoist awards, dan konser musik lainnya. Dalam upaya membangun tali persaudaraan antar sesama mahasiswa Sistem Informasi, sekaligus menjadi momentum dalam bertambahnya usia yang ke – 5 tahun ini."},{"type":"heading","text":"Penampilan Guest Star"},{"type":"paragraph","text":"Revoist 5.0 semakin meriah dengan kehadiran dua guest star, yaitu Anesthecy dan Minionska, yang membawa energi baru ke dalam perayaan Dies Natalis Himsika ke-5. Anesthecy, yang dijuluki <i>“The Rising Star of Alternative Rock in Karawang”</i>, tampil kuat dengan karakter musik alternatif rock dan panggung yang energik. Performa mereka yang penuh emosi sukses membangkitkan antusiasme penonton dan menjadikan malam puncak Revoist 5.0 semakin hidup serta berkesan."},{"type":"paragraph","text":"Sementara itu Minionska merupakan band yang berdiri sejak 2014 dan memiliki akar komunitas yang solid, turut menghadirkan hiburan yang enerjik dan ritmis. Lewat musik penuh semangat yang mengajak penonton untuk “skank and groove”, mereka berhasil menciptakan suasana ceria dan meningkatkan kebersamaan seluruh peserta."},{"type":"paragraph","text":"Kehadiran kedua guest star menjadi salah satu sorotan utama Revoist 5.0, memberikan pengalaman hiburan yang meriah dan meninggalkan kesan positif bagi seluruh mahasiswa."},{"type":"paragraph","text":"Secara keseluruhan, rangkaian acara Revoist 5.0 menunjukkan bahwa perayaan Dies Natalis Himsika bukan sekadar penanda bertambahnya usia, tetapi juga cerminan semangat, kreativitas, dan kebersamaan keluarga besar Sistem Informasi."},{"type":"paragraph","text":"Dengan mengusung tema <i>“Symphony in Celebration of Light, Laughs, and Legacy”</i>, kegiatan ini berhasil menghadirkan atmosfer penuh energi dan kebanggaan atas perjalanan Himsika hingga usia kelima. Seluruh aktivitas yang terselenggara memperlihatkan rasa memiliki terhadap himpunan serta memperkuat solidaritas antar anggota untuk terus berkontribusi membangun HIMSIKA ke arah yang lebih baik."},{"type":"heading","text":"Penutup"},{"type":"paragraph","text":"Dengan terselenggaranya Revoist 5.0 dengan sukses, diharapkan semangat kebersamaan, rasa kekeluargaan, serta kebanggaan terhadap Himpunan Mahasiswa Sistem Informasi dapat terus tumbuh dan terpelihara di hati setiap anggotanya.<br />Kegiatan ini tidak hanya menjadi ajang perayaan bertambahnya usia HIMSIKA, tetapi juga menjadi momen reflektif untuk meneguhkan komitmen dalam menjaga solidaritas, mengasah kreativitas, serta meneruskan semangat perjuangan demi mengharumkan nama organisasi."},{"type":"paragraph","text":"Semoga makna “api” yang menggambarkan kekuatan, keberanian, dan tekad yang tak pernah padam dapat senantiasa menginspirasi seluruh mahasiswa Sistem Informasi dalam perjalanan akademik maupun organisasinya. Dengan demikian, Revoist 5.0 bukan sekadar perayaan tahunan, melainkan simbol dari semangat untuk menjadi generasi yang tangguh, inovatif, berkarakter, dan berintegritas tinggi dalam memperkuat Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang."}]'::jsonb, 'HIMSIKA'),
(8, '“Navigasi Karir Lulusan Sistem Informasi: Dua Mahasiswa, Dua Perspektif”', 'Berita', '6 November 2025', '2025-11-06', '', 'Mahasiswa Sistem Informasi angkatan 2022, Ariel Syahwal dan Muhammad Rizky Saputra, kini telah mendahului rekan-rekan seangkatan mereka dalam menapaki dunia profesional, memanfaatkan ilmu yang didapat di bangku kuliah…', '[{"type":"gallery","images":[{"src":"","alt":"1737448588140-Jenjang-Karir-Programmer-Tips-Sukses-di-Industri-IT"},{"src":"","alt":"e190fcc7-ef2c-48e2-8742-c71cffc154ee"},{"src":"","alt":"1724123012048-HNL1307"},{"src":"","alt":"1723718413580-HNL108"}]},{"type":"heading","text":"Judul Artikel\n \n \n :root {\n --title-font-serif: ''Merriweather'', serif;\n }\n\n h2 {\n font-family: var(--title-font-serif);\n font-size: 1,rem;\n color: #1e293b;\n margin-top: 0px;\n line-height: 1.3;\n }\n \n\n\n\n \n Navigasi Karir Lulusan Sistem Informasi: Dua Mahasiswa, Dua Perspektif"},{"type":"paragraph","text":"Mahasiswa Sistem Informasi angkatan 2022, Ariel Syahwal dan Muhammad Rizky Saputra, kini telah mendahului rekan-rekan seangkatan mereka dalam menapaki dunia profesional, memanfaatkan ilmu yang didapat di bangku kuliah untuk bertransformasi cepat menjadi praktisi di berbagai bidang teknologi informasi. Bagaimana keduanya berhasil menyeimbangkan kuliah dan karier, mengapa mereka menekankan pentingnya pengalaman di luar kampus, dan apa saja kiat sukses yang mereka bagikan, menjadi sorotan utama dalam persiapan menghadapi ketatnya persaingan industri."},{"type":"paragraph","text":"Jalur yang ditempuh Ariel dan Rizky untuk mendapatkan kesempatan kerja menunjukkan pentingnya jaringan profesional. Ariel, yang saat ini berperan sebagai Analyst di Kementerian Koperasi dan Duta di Bursa Efek Indonesia, mendapat kepercayaan karena performa magang yang baik sejak semester lima dan relasi yang kuat. Pengalaman dan kinerja apiknya membuahkan panggilan langsung untuk menyukseskan program digitalisasi pemerintah. Sementara itu, Rizky, yang sedang magang di departemen Management Information System (MIS) perusahaan otomotif, justru mendapatkan posisi dari limpahan peluang seorang teman. Dari pengalaman ini, Rizky menyadari kekeliruan umum mahasiswa yang terlalu fokus pada satu posisi (seperti Web Developer) dan menyarankan agar calon pelamar lebih fleksibel dengan menyiapkan CV yang general agar dapat menjangkau lebih banyak posisi IT yang relevan."},{"type":"paragraph","text":"Keduanya sepakat bahwa ilmu dari jurusan Sistem Informasi sangat relevan dengan kebutuhan industri, namun dengan fokus berbeda. Ariel menilai relevansi kuliah mencapai 80%, terutama karena membantu membentuk etika profesional dan pengetahuan dasar sebelum melangkah ke level yang lebih serius. Sejalan dengan perannya di MIS, Rizky berpendapat bahwa yang paling esensial adalah kemampuan analisis data dan pengelolaan basis data, yang menjadi fondasi utama di bidangnya. Tantangan terbesar, menurut Ariel, bukanlah dari luar, melainkan bagaimana memanfaatkan setiap peluang yang ada untuk terus berkembang."},{"type":"paragraph","text":"Baik Ariel maupun Rizky menekankan bahwa soft skill tidak kalah penting dari kemampuan teknis. Rizky menyoroti pentingnya kemampuan berbicara di depan umum, berpikir kritis, dan kepemimpinan sebagai keterampilan dasar yang harus diasah untuk wawancara dan interaksi kerja. Selain itu, kemampuan berkomunikasi dan etika profesi yang ditekankan Ariel, bersama dengan perluasan relasi yang luas, menjadi modal esensial di lingkungan kerja."},{"type":"paragraph","text":"Melihat prospek karier, Ariel cenderung melihat posisi dengan permintaan pasar yang tinggi dan realistis, seperti Digital Marketing, Data Scientist, dan berbagai peran Programmer atau Analyst. Sebaliknya, Rizky melihat potensi besar pada bidang yang baru dan minim pesaing, seperti Web 3.0 Developer, sebuah peran yang sangat menjanjikan seiring berkembangnya teknologi blockchain dan smart contract. Ia juga merekomendasikan peran non-coding seperti System Analyst atau Project Manager bagi lulusan yang memiliki kemampuan nalar dan analisis yang kuat."},{"type":"paragraph","text":"Sebagai penutup, kedua profesional muda ini mendorong mahasiswa untuk segera aktif dan berani mengambil resiko. Rizky memberikan pesan tegas agar mahasiswa tidak menyia-nyiakan empat tahun kuliah hanya untuk masuk kelas, melainkan harus dipakai untuk magang, membangun portofolio, dan mencari sertifikasi tambahan sebagai bukti nyata kemampuan. Senada dengan hal tersebut, Ariel meyakini bahwa masa kuliah adalah waktu terbaik untuk berani salah dan gagal, karena kesalahan di dunia profesional akan menghasilkan pembelajaran, bukan kegagalan yang fatal. Keduanya menyimpulkan bahwa kunci kesiapan adalah memperbanyak relasi, aktif sejak semester awal, dan terus meningkatkan nilai diri agar siap bersaing di dunia profesional."},{"type":"paragraph","text":"narasumber: Muhammad Rizky Saputra, Ariel Syahwal"}]'::jsonb, 'HIMSIKA'),
(9, 'Information System Gathering  “Building Sense of Solidarity and Warmth While Embracing Responsibility”', 'Berita', '28 Oktober 2025', '2025-10-28', '', 'Information System Gathering', '[{"type":"gallery","images":[{"src":"","alt":"Salinan DSCF9146"},{"src":"","alt":"Salinan DSCF8993"},{"src":"","alt":"Salinan DSCF8964"},{"src":"","alt":"Salinan DSCF8843"},{"src":"","alt":"Salinan DSCF8655"},{"src":"","alt":"Salinan DSCF8594"},{"src":"","alt":"Salinan IMG_0381"},{"src":"","alt":"Salinan IMG_0156"},{"src":"","alt":"Salinan DSCF8315"},{"src":"","alt":"Salinan DSCF8166"},{"src":"","alt":"Salinan DSCF7985"},{"src":"","alt":"Salinan DSCF7587"}]},{"type":"paragraph","text":"Information System Gathering"},{"type":"paragraph","text":"“Building Sense of Solidarity and Warmth While Embracing Responsibility”"},{"type":"paragraph","text":"Pada hari Sabtu dan Minggu, 11-12 Oktober 2025, Himpunan Mahasiswa Sistem Informasi Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang sukses menyelenggarakan Information System Gathering 2025. Kegiatan ini mengusung tema “Building Sense of Solidarity and Warmth While Embracing Responsibility” yang dapat diartikan membangun rasa solidaritas dan kehangatan dengan tetap memikul rasa tanggung jawab, ini merupakan salah satu rangkaian kaderisasi yang memiliki peran penting sebagai proses pembinaan untuk mengembangkan potensi para mahasiswa melalui penanaman nilai-nilai tertentu, sehingga mampu mencetak mahasiswa-mahasiswa yang tangguh dan berkualitas."},{"type":"paragraph","text":"Tujuan dan Bentuk Kegiatan"},{"type":"paragraph","text":"Information System Gathering 2025 bertujuan untuk mempererat tali persaudaraan antar mahasiswa Program Studi Sistem Informasi, khususnya bagi mahasiswa angkatan 2025, agar terjalin hubungan yang solid dan harmonis. Selain itu, sebagai wadah untuk berbagi ilmu, pengalaman, serta wawasan yang bermanfaat, yang dapat menjadi bekal bagi mahasiswa dalam menghadapi perjalanan akademik maupun mempersiapkan diri memasuki dunia kerja."},{"type":"paragraph","text":"Acara ini bersifat pemaparan materi pokok yang berkaitan dengan Sistem Informasi, dan juga pelatihan keilmuan seperti project analisis SWOT yang di tuangkan hasilnya ke dalam Business Process Modeling and Notation (BPMN). Lalu dilanjut Pemilihan Ketua Angkatan Sistem Informasi 2025 dan pengukuhan mahasiswa Sistem Informasi angkatan 2025, serta beberapa rangkaian acara yang berorientasi sebagai pengakraban dan sarana untuk mempererat tali persaudaraan seperti pentas seni dan games."},{"type":"paragraph","text":"Kegiatan Information System Gathering terdiri dari;"},{"type":"list","ordered":true,"items":["<p dir=\"ltr\" role=\"presentation\">Pemaparan Materi “From Campus To Career: Your Journey As Anak SI” dengan pemateri Fadia Lutfiyah Ananda.</p>","<p dir=\"ltr\" role=\"presentation\">Talkshow “From Campus To Career: Navigating The SI Industry” dengan pembicara Ismail Adhiya Adha, S.Kom. dan Mayland Trifena, S.Kom.</p>","<p dir=\"ltr\" role=\"presentation\">Pemaparan Materi (Praktik) “Your First Step As Anak SI: Belajar Problem Solving dengan SWOT dan Flowchart” dengan pemateri Muhammad Fajar Nadillah.</p>","<p dir=\"ltr\" role=\"presentation\">Outbound yang bertujuan untuk membangun kerja sama tim.</p>","<p dir=\"ltr\" role=\"presentation\">Sharing Session bersama pengurus Himsika yang bertujuan untuk memberikan wawasan serta motivasi kepada mahasiswa baru mengenai dunia perkuliahan dan organisasi.</p>","<p dir=\"ltr\" role=\"presentation\">Pemilihan Ketua Angkatan yang bertujuan untuk memilih sosok pemimpin yang akan mewakili dan mengkoordinasikan mahasiswa Sistem Informasi angkatan 2025.</p>","<p dir=\"ltr\" role=\"presentation\">Pentas Seni untuk mempererat hubungan dan menumbuhkan rasa apresiasi terhadap keberagaman.</p>","<p dir=\"ltr\" role=\"presentation\">Pengukuhan yang menjadi puncak kegiatan, di mana seluruh Mahasiswa Baru Sistem Informasi Universitas Singaperbangsa Karawang angkatan 2025 secara resmi dikukuhkan sebagai bagian dari keluarga besar Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang.</p>","<p dir=\"ltr\" role=\"presentation\">Games, Color Party, dan Putar Hadiah dilaksanakan untuk menambah keseruan dan mempererat kebersamaan antar peserta melalui berbagai permainan interaktif dan momen penuh warna.</p>"]},{"type":"paragraph","text":"Berdasarkan serangkaian kegiatan yang telah dilaksanakan, dapat disimpulkan bahwa Information System Gathering 2025 merupakan kegiatan yang tidak hanya berfokus pada pengembangan wawasan akademik, tetapi juga pada pembentukan karakter, solidaritas, dan rasa kebersamaan antar mahasiswa. Melalui rangkaian kegiatan seperti pemaparan materi, talkshow, dan praktik pembelajaran, peserta dibekali pengetahuan serta motivasi untuk menghadapi dunia perkuliahan dan karier di bidang Sistem Informasi. Sementara itu, kegiatan outbond, sharing session, pentas seni, hingga color party menjadi sarana untuk mempererat hubungan, menumbuhkan semangat kerja sama, dan menciptakan suasana kekeluargaan yang hangat. Puncaknya, melalui prosesi pengukuhan, mahasiswa baru Sistem Informasi angkatan 2025 resmi menjadi bagian dari keluarga besar Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang, dengan harapan mampu menjadi generasi yang solid, berkompeten, dan berintegritas tinggi."},{"type":"paragraph","text":"Penutup"},{"type":"paragraph","text":"Melalui rangkaian kegiatan yang terencana dengan baik, Information System Gathering 2025 berhasil mewujudkan tujuannya dalam mempererat rasa persaudaraan dan menumbuhkan semangat kebersamaan di kalangan mahasiswa baru Sistem Informasi. Setiap agenda, mulai dari penyampaian materi, talkshow inspiratif, hingga kegiatan interaktif seperti outbond dan color party, disusun untuk menanamkan nilai tanggung jawab, kekompakan, serta kesadaran akan pentingnya peran mahasiswa sebagai bagian dari keluarga besar Himpunan Mahasiswa Sistem Informasi."},{"type":"paragraph","text":"Dengan berakhirnya seluruh kegiatan, diharapkan para peserta mampu mengimplementasikan nilai-nilai positif yang diperoleh selama acara berlangsung. Semangat kebersamaan, tanggung jawab, dan solidaritas yang tumbuh dalam kegiatan ini menjadi modal berharga bagi mahasiswa baru untuk terus berkembang, berkontribusi aktif di lingkungan kampus, dan menjadi generasi Sistem Informasi yang kompeten, berkarakter, serta berintegritas tinggi."}]'::jsonb, 'HIMSIKA'),
(10, 'LKMM-PD “Membangun Pemimpin Berkarakter: Cerdas, Tanggap, Bertanggung Jawab”', 'Berita', '25 September 2025', '2025-09-25', '', 'Latihan Keterampilan Manajemen Mahasiswa Pra-Dasar 2025“Membangun Pemimpin Berkarakter: Cerdas, Tanggap, Bertanggung Jawab”', '[{"type":"gallery","images":[{"src":"","alt":"DSCF3966"},{"src":"","alt":"DSCF3970"},{"src":"","alt":"DSCF4135"},{"src":"","alt":"DSCF4148"},{"src":"","alt":"DSCF4165"},{"src":"","alt":"DSCF4232"},{"src":"","alt":"DSCF4352"},{"src":"","alt":"DSCF4374"},{"src":"","alt":"DSCF4402"},{"src":"","alt":"DSCF4466"},{"src":"","alt":"DSCF4517"},{"src":"","alt":"DSCF5039"},{"src":"","alt":"DSCF5051"}]},{"type":"paragraph","text":"<strong>Latihan Keterampilan Manajemen Mahasiswa Pra-Dasar 2025<br />“Membangun Pemimpin Berkarakter: Cerdas, Tanggap, Bertanggung Jawab”<br /></strong>"},{"type":"paragraph","text":"Pada hari Selasa 26 Agustus 2025, Himpunan Mahasiswa Sistem Informasi Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang sukses menyelenggarakan program kerja yang bernama LKMM Pra-Dasar 2025. Kegiatan ini mengusung tema “Membangun Pemimpin Berkarakter: Cerdas, Tanggap, Bertanggung Jawab” yang berlangsung di Aula Syekh Quro UNSIKA yang dihadiri oleh Mahasiswa Baru Program Studi Sistem Informasi Angkatan 2025."},{"type":"paragraph","text":"<strong>Tujuan dan Bentuk Kegiatan </strong>"},{"type":"paragraph","text":"Latihan Keterampilan Manajemen Mahasiswa Pra-Dasar 2025 yang diselenggarakan oleh Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang merupakan program kerja berupa bagian dari tahapan kaderisasi tingkat prodi yang bertujuan untuk menguasai karakteristik dan potensi masing-masing mahasiswa baru, membekali mahasiswa baru dengan keterampilan dasar dalam berkepemimpinan dan menjadi pribadi yang berkarakter, tanggap dan tanggung jawab."},{"type":"paragraph","text":"Kegiatan LKMM Pra-Dasar 2025 terdiri dari;"},{"type":"list","ordered":true,"items":["Talkshow dengan tema “Pengenalan Jurusan Sistem Informasi” yang bertujuan untuk memberikan wawasan yang lebih mendalam mengenai jurusan Sistem Informasi.","Pemaparan materi “Karakter 3D: Mengasah Diri, Memahami Dunia, Memberi Dampak” sesi ini membahas cara mengembangkan karakter diri, memahami dinamika global, dan memberikan kontribusi positif bagi lingkungan sekitar.","Pemaparan materi “From Zero to Leader: Membentuk dan Mengembangkan Karakter Pemimpin Sejak Dini” yang akan membekali mahasiswa dengan pengetahuan dan keterampilan dasar untuk membentuk serta mengasah jiwa kepemimpinan sejak awal.","Wawasan tentang keorganisasian melalui materi dari “Himsika” dan “Permikomnas” untuk mendapatkan pemahaman tentang dunia organisasi."]},{"type":"paragraph","text":"Berdasarkan serangkaian kegiatan yang telah dijelaskan, dapat disimpulkan bahwa LKMM Pra-Dasar 2025 merupakan program komprehensif yang dirancang untuk membentuk mahasiswa baru menjadi individu yang tidak hanya cerdas secara akademis, tetapi juga memiliki karakter, kepemimpinan, dan pemahaman organisasi yang kuat. Melalui berbagai sesi, mahasiswa akan dipandu untuk mengenali lebih dalam profesi dan ruang lingkup jurusan Sistem Informasi. Selain itu, mereka akan dibekali dengan keterampilan dasar untuk mengembangkan potensi diri dan mengasah jiwa kepemimpinan sejak dini. Tak hanya itu, pemaparan dari Himsika dan Permikomnas akan memberikan wawasan praktis mengenai dinamika dunia organisasi, yang menjadi bekal penting untuk beradaptasi dan berkontribusi secara aktif di lingkungan kampus. Dengan demikian, LKMM Pra-Dasar 2025 tidak hanya berfungsi sebagai pengenalan dunia perkuliahan, melainkan juga sebagai fondasi untuk mempersiapkan mahasiswa menghadapi tantangan dunia kerja yang semakin kompetitif di masa depan."},{"type":"paragraph","text":"<strong>Rangkaian Acara </strong>"},{"type":"paragraph","text":"Acara dimulai dengan Opening Ceremony yang mencakup laporan ketua pelaksana dan sambutan-sambutan. Lalu dilanjut ke inti kegiatan yaitu Talkshow “Pengenalan Prodi Sistem Informasi”, para dosen akan memperkenalkan jurusan dan berinteraksi langsung dengan mahasiswa melalui sesi tanya jawab. Selanjutnya, ada dua sesi materi penting. Sesi pertama, “Karakter 3D: Mengasah Diri, Memahami Dunia, Memberi Dampak” yang akan membahas cara mengembangkan diri, memahami dunia, dan memberikan dampak positif. Sesi kedua, <b>“</b>From Zero to Leader: Membentuk dan Mengembangkan Karakter Pemimpin Sejak Dini”, akan membekali mahasiswa dengan dasar-dasar kepemimpinan. Kedua sesi ini diselingi dengan istirahat makan dan sholat, serta dilengkapi kuis dan dokumentasi."},{"type":"paragraph","text":"Menjelang sore, fokus acara beralih ke wawasan organisasi melalui “Sharing Session Himsika dan Permikomnas”. Mahasiswa berkesempatan mengenal lebih dekat dunia organisasi kemahasiswaan. Acara dilanjutkan dengan Focus Group Discussion (FGD) dan sesi debat, yang memungkinkan peserta mempraktikkan keterampilan berpikir kritis dan berargumen. Seluruh rangkaian kegiatan diakhiri dengan Closing Ceremony yang diisi dengan prakata dari ketua pelaksana dan ketua Himsika, serta sambutan penutup dari Koordinator Prodi, sebelum acara resmi ditutup dan dilanjutkan dengan sesi dokumentasi."},{"type":"paragraph","text":"<strong>Penutup</strong>"},{"type":"paragraph","text":"Melalui serangkaian kegiatan yang terstruktur, LKMM Pra-Dasar 2025 berhasil mencapai tujuannya untuk membekali mahasiswa baru dengan fondasi yang kuat. Setiap sesi, mulai dari pengenalan jurusan hingga materi pembentukan karakter, dirancang untuk memastikan para peserta memiliki pemahaman yang komprehensif. Mereka tidak hanya diperkenalkan pada dunia akademik, tetapi juga diajak untuk mengembangkan diri menjadi individu yang cerdas, tanggap, dan bertanggung jawab. Acara ini menjadi bukti nyata komitmen Himpunan Mahasiswa Sistem Informasi dalam menghasilkan generasi penerus yang unggul."},{"type":"paragraph","text":"Secara keseluruhan, LKMM Pra-Dasar 2025 menjadi lebih dari sekadar kegiatan orientasi. Acara ini merupakan sebuah investasi jangka panjang bagi masa depan mahasiswa. Paparan materi tentang kepemimpinan dan wawasan organisasi membuka cakrawala baru bagi para peserta. Mereka jadi lebih siap untuk beradaptasi dengan dinamika perkuliahan dan berkontribusi aktif dalam berbagai kegiatan kemahasiswaan. Kemampuan yang diasah, seperti berpikir kritis dan berinteraksi dalam diskusi, akan menjadi bekal berharga yang relevan hingga mereka terjun ke dunia kerja."},{"type":"paragraph","text":"Dengan berakhirnya seluruh rangkaian acara, diharapkan para peserta dapat mengaplikasikan semua ilmu dan keterampilan yang telah mereka peroleh. Semangat kepemimpinan, karakter yang kuat, dan pemahaman tentang organisasi adalah modal utama untuk meraih kesuksesan, baik di kampus maupun di luar kampus. LKMM Pra-Dasar 2025 telah meletakkan dasar yang kokoh, kini giliran mahasiswa baru untuk terus berkembang dan menjadi pemimpin masa depan yang mampu memberikan dampak positif bagi masyarakat."}]'::jsonb, 'HIMSIKA'),
(11, 'Silogy Expo “Innovating Business and Finance: The Role of Data and Cryptocurrency in The Era of Digital Business”', 'Berita', '25 September 2025', '2025-09-25', '', 'Silogy Expo “Innovating Business and Finance: The Role of Data and Cryptocurrency in The Era of Digital Business”', '[{"type":"gallery","images":[{"src":"","alt":"Salinan DSCF2874"},{"src":"","alt":"Salinan IMG_0750"},{"src":"","alt":"Salinan IMG_0793"},{"src":"","alt":"Salinan IMG_0846"},{"src":"","alt":"Salinan IMG_0862"},{"src":"","alt":"Salinan IMG_0912"},{"src":"","alt":"Salinan IMG_0951"},{"src":"","alt":"Salinan IMG_1105"},{"src":"","alt":"Salinan IMG_1155"},{"src":"","alt":"Salinan IMG_1282"},{"src":"","alt":"Salinan IMG_1347"},{"src":"","alt":"Salinan IMG_1352"},{"src":"","alt":"Salinan IMG_1375"},{"src":"","alt":"Salinan DSCF2900"}]},{"type":"paragraph","text":"<strong><b><i>Silogy Expo </i></b><br /><i>“Innovating Business and Finance: The Role of Data and Cryptocurrency in The Era of Digital Business”</i></strong>"},{"type":"paragraph","text":"Pada hari Minggu, 10 Agustus 2025, Himpunan Mahasiswa Sistem Informasi Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang sukses menyelenggarakan Silogy Expo 2025. Acara ini merupakan rangkaian terakhir dari Education Fair 2025 yang mengusung semangat kolaborasi, kreativitas, dan edukasi. Kegiatan berlangsung di Ground Floor Mall Technomart Karawang dengan menghadirkan mahasiswa, akademisi, serta masyarakat umum."},{"type":"paragraph","text":"<strong>Tujuan dan Bentuk Kegiatan </strong>"},{"type":"paragraph","text":"Silogy Expo 2025 hadir sebagai wadah pengembangan diri, inovasi, serta perluasan wawasan mahasiswa dan masyarakat dalam menghadapi era digital. Program kerja ini terdiri dari tiga rangkaian utama, yaitu:"},{"type":"list","ordered":true,"items":["Perlombaan Tingkat Nasional<br />Perlombaan ini menjadi ajang kompetisi kreatif yang melibatkan siswa SMA/SMK, dan mahasiswa dari berbagai Universitas di Indonesia. Tujuannya untuk mengasah keterampilan, memperkuat semangat kompetitif, serta membuka ruang kolaborasi antar siswa SMA/SMK dan mahasiswa di tingkat nasional.<br /><br />","Talkshow <br />Talkshow Silogy Expo 2025 mengangkat tema “Menabung vs Investasi Crypto: Strategi Cerdas di Era Keuangan Digital”. Acara ini menghadirkan dua narasumber dosen Fakultas Ilmu Komputer Unsika, yaitu Apriade Voutama, M.Kom. dan Ade Andri Hendriadi, S.Si., M.Kom.. Melalui sesi ini, peserta mendapatkan pemahaman mendalam mengenai strategi finansial modern, perbandingan antara menabung dan investasi, serta peluang dan risiko yang ada di era keuangan digital. Talkshow dipandu oleh Nabila Latifa Tullaili dan Muhammad Luthfi Ramadhan sebagai Master of Ceremony.<br /><br />","Pameran Mahasiswa Sistem Informasi <br />Pameran menjadi ruang apresiasi karya-karya inovatif mahasiswa. Berbagai produk seperti ide, dan karya kreatif ditampilkan untuk menunjukkan potensi generasi muda dalam menjawab tantangan teknologi, bisnis digital, dan seni."]},{"type":"paragraph","text":"<strong>Penutup</strong>"},{"type":"paragraph","text":"Berdasarkan rangkaian kegiatan yang telah diselenggarakan, Silogy Expo 2025 menjadi program komprehensif yang tidak hanya menghadirkan hiburan, tetapi juga sarana edukasi dan pengembangan diri. Acara ini membuktikan bahwa mahasiswa mampu menghadirkan kegiatan bermanfaat yang menjembatani akademisi, praktisi, dan masyarakat."},{"type":"paragraph","text":"Melalui kompetisi, peserta belajar untuk berkreasi dan berinovasi. Lewat talkshow, peserta mendapat pengetahuan baru tentang strategi keuangan di era digital. Dan lewat pameran, karya mahasiswa mendapat ruang apresiasi yang lebih luas."},{"type":"paragraph","text":"Dengan berakhirnya Silogy Expo 2025, diharapkan semangat inovasi, kolaborasi, dan pembelajaran terus berlanjut. Acara ini menjadi bukti nyata komitmen Himpunan Mahasiswa Sistem Informasi dalam menciptakan wadah bagi mahasiswa untuk berkembang dan memberikan kontribusi positif bagi masyarakat."}]'::jsonb, 'HIMSIKA'),
(12, 'Information System Company Tour 2025 “Tech Insight Tour: Menjelajahi Transformasi Digital dalam Bisnis”', 'Berita', '29 Juli 2025', '2025-07-29', '', 'Information System Company Tour 2025 “Tech Insight Tour: Menjelajahi Transformasi Digital dalam Bisnis”', '[{"type":"gallery","images":[{"src":"","alt":"IMG_9278"},{"src":"","alt":"IMG_9112"},{"src":"","alt":"IMG_9077"},{"src":"","alt":"IMG_9064"},{"src":"","alt":"IMG_9061"},{"src":"","alt":"IMG_8920"},{"src":"","alt":"IMG_8847"},{"src":"","alt":"IMG_8786"},{"src":"","alt":"IMG_1107"},{"src":"","alt":"IMG_1062"}]},{"type":"paragraph","text":"<strong>Information System Company Tour 2025 <br /></strong><strong>“<em>Tech Insight Tour</em>: Menjelajahi Transformasi Digital dalam Bisnis”</strong>"},{"type":"paragraph","text":"Pada hari Kamis 19 Juni 2025, Himpunan Mahasiswa Sistem Informasi Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang sukses menyelenggarakan program kerja yang bernama “Information System Company Tour 2025”. Kegiatan ini mengusung tema “Tech Insight Tour: Menjelajahi Transformasi Digital dalam Bisnis” yang berlangsung di PT Industri Telekomunikasi Indonesia (INTI) dan dihadiri oleh sebagian Mahasiswa Aktif Sistem Informasi Unsika."},{"type":"paragraph","text":"<strong>Tujuan dan Bentuk Kegiatan </strong>"},{"type":"paragraph","text":"Information System Company Tour 2025 yang diselenggarakan oleh Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang merupakan program kerja berupa kunjungan ke perusahaan-perusahaan yang bergerak di bidang sistem informasi yang bertujuan untuk memberikan kesempatan kepada mahasiswa aktif dan pengurus untuk memberikan pengetahuan dan wawasan tentang industri sistem informasi dan mempersiapkan mahasiswa untuk berkarir di bidang ini."},{"type":"paragraph","text":"Kegiatan Information System Company Tour 2025 terdiri dari;"},{"type":"list","ordered":true,"items":["Seminar Perusahaan tentang Sistem Informasi: Profil, visi, misi, dan proyek sistem informasi. Selanjutnya tren dan inovasi teknologi baru, perubahan regulasi, strategi bisnis, dan tren pasar.","Sesi Tanya Jawab: Peserta dapat bertanya langsung kepada pembicara.","Tur Fasilitas: Melihat implementasi sistem informasi di perusahaan.","Diskusi Panel: Membahas tren, keterampilan, dan saran karir di bidang sistem informasi."]},{"type":"paragraph","text":"Kegiatan ini juga memberikan pengetahuan dan wawasan tentang teknologi informasi, mempersiapkan peserta untuk berkarir di bidang ini dengan pengenalan perusahaan, inovasi terkini, diskusi interaktif, dan kunjungan fasilitas."},{"type":"paragraph","text":"<strong>Rangkaian Acara </strong>"},{"type":"paragraph","text":"Acara dimulai dengan sambutan dari perwakilan PT Industri Telekomunikasi Indonesia (INTI) yang menjelaskan tugas dan tanggung jawab fungsi IT dalam perusahaan serta memaparkan katalog produk unggulan dari PT Industri Telekomunikasi Indonesia (INTI). Setelah sesi sambutan, para peserta diajak mengunjungi showroom yang menampilkan berbagai produk teknologi milik PT Industri Telekomunikasi Indonesia (INTI), sehingga peserta dapat melihat langsung inovasi yang telah dikembangkan."},{"type":"paragraph","text":"Salah satu bagian menarik dari kegiatan ini adalah diskusi interaktif bersama para profesional di bidang teknologi. Dalam sesi ini, peserta tampak antusias bertanya seputar fungsi, cara kerja, dan peran dari masing-masing produk yang dipamerkan. Interaksi ini memberikan pemahaman yang lebih mendalam mengenai implementasi teknologi di dunia industri telekomunikasi."},{"type":"paragraph","text":"<strong>Penutup</strong>"},{"type":"paragraph","text":"Information System Company Tour 2025 berhasil mencapai tujuan utamanya, yaitu membuka wawasan mahasiswa aktif Sistem Informasi Unsika mengenai dunia kerja di bidang Sistem Informasi. Melalui rangkaian kegiatan yang informatif dan interaktif, para peserta mendapatkan pemahaman yang lebih mendalam tentang bagaimana teknologi informasi diimplementasikan dalam industri, mulai dari proses kerja, peran strategis IT, hingga inovasi produk yang dihasilkan perusahaan."},{"type":"paragraph","text":"Tak hanya menambah pengetahuan, kegiatan ini juga membuka peluang untuk menjalin koneksi baru dengan para profesional di bidang teknologi. Interaksi langsung yang terbangun selama kunjungan menjadi bekal berharga bagi mahasiswa dalam mempersiapkan diri menghadapi dunia profesional. Pengalaman ini memberikan gambaran nyata tentang tantangan dan peluang yang ada di industri Sistem Informasi."},{"type":"paragraph","text":"Program ini diharapkan dapat menjadi inspirasi bagi terselenggaranya kegiatan serupa di masa mendatang. Dengan bekal ilmu dan wawasan yang diperoleh, mahasiswa aktif Sistem Informasi Unsika semakin percaya diri dan optimis untuk mengambil peran aktif dalam menghadapi tantangan era digital. Information System Company Tour 2025 bukan hanya sekadar kunjungan, melainkan sebuah perjalanan menuju masa depan yang penuh potensi."}]'::jsonb, 'HIMSIKA'),
(13, 'Make Connection 2025 “Kolaborasi Antar Himpunan Mahasiswa untuk Meningkatkan Value Organisasi dan Mempererat Kekeluargaan dengan Cara Membangun Koneksi”', 'Berita', '29 Juli 2025', '2025-07-29', '', 'Make Connection 2025“Kolaborasi Antar Himpunan Mahasiswa untuk Meningkatkan Value Organisasi dan Mempererat Kekeluargaan dengan Cara Membangun Koneksi”', '[{"type":"gallery","images":[{"src":"","alt":"Salinan _MG_9635"},{"src":"","alt":"Salinan _MG_9638"},{"src":"","alt":"Salinan _MG_9639"},{"src":"","alt":"Salinan _MG_9677"},{"src":"","alt":"Salinan _MG_9729"},{"src":"","alt":"Salinan IMG_0107"},{"src":"","alt":"Salinan IMG_0118"},{"src":"","alt":"Salinan IMG_0179"},{"src":"","alt":"Salinan IMG_0389"},{"src":"","alt":"Salinan IMG_0433"},{"src":"","alt":"Salinan IMG_0434"},{"src":"","alt":"Salinan IMG_0478"}]},{"type":"paragraph","text":"<strong>Make Connection 2025<br /></strong><strong>“Kolaborasi Antar Himpunan Mahasiswa untuk Meningkatkan Value Organisasi dan Mempererat Kekeluargaan dengan Cara Membangun Koneksi”</strong>"},{"type":"paragraph","text":"Pada hari Sabtu, 5 Juli 2025, Himpunan Mahasiswa Sistem Informasi Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang sukses menyelenggarakan program kerja yang bernama “Make Connection 2025”. Kegiatan ini mengusung tema “Kolaborasi Antar Himpunan Mahasiswa untuk Meningkatkan Value Organisasi dan Mempererat Kekeluargaan dengan Cara Membangun Koneksi” yang berlangsung di Fakultas Sains dan Teknologi Universitas Islam Negeri Sunan Gunung Djati Bandung yang dihadiri oleh pengurus Himsika dan pengurus Himpunan Mahasiswa Teknik Informatika Universitas Islam Negeri Sunan Gunung Djati Bandung (Himatif UIN SGD Bandung)."},{"type":"paragraph","text":"<strong>Tujuan dan Bentuk Kegiatan </strong>"},{"type":"paragraph","text":"Make Connection diselenggarakan dengan tujuan untuk menggali informasi, memperluas wawasan, serta membangun relasi antara Himpunan Mahasiswa Sistem Informasi Unsika di luar kampus. Kegiatan ini juga bertujuan meningkatkan kinerja, sudut pandang akademik dan keorganisasian pengurus, serta menjalin hubungan baik yang dapat menjadi bekal dalam pengembangan himpunan kedepannya."},{"type":"paragraph","text":"Sebagai bentuk nyata dari tujuan tersebut, Make Connection merupakan kegiatan kunjungan atau studi banding ke himpunan mahasiswa di luar Universitas Singaperbangsa Karawang, yaitu Himpunan Mahasiswa Teknik Informatika Universitas Islam Negeri Sunan Gunung Djati Bandung (Himatif UIN SGD Bandung). Kegiatan ini mencakup berbagai agenda seperti perkenalan antar himpunan, sharing session, forum group discussion, serta pembahasan seputar akademik dan keorganisasian. Seluruh rangkaian acara ini menjadi wadah pengembangan diri bagi pengurus Himpunan Mahasiswa Sistem Informasi, dengan harapan mampu menumbuhkan perspektif baru dan meningkatkan kualitas organisasi secara berkelanjutan."},{"type":"paragraph","text":"<strong>Rangkaian Acara </strong>"},{"type":"paragraph","text":"Rangkaian kegiatan Make Connection diawali dengan sambutan dari perwakilan masing-masing himpunan serta pihak tuan rumah, yang memberikan apresiasi dan harapan atas terjalinnya hubungan baik antar organisasi mahasiswa. Sambutan ini menjadi pembuka suasana hangat dan kolaboratif selama kegiatan berlangsung. Selanjutnya, dilakukan pemaparan mengenai struktur kepengurusan dan tugas dari Steering Committee serta Badan Pengurus Harian (SC BPH), yang bertujuan untuk memberikan pemahaman lebih mendalam tentang sistem organisasi dan pembagian peran di dalamnya."},{"type":"paragraph","text":"Kegiatan kemudian dilanjutkan dengan <i>forum group discussion</i> yang menjadi wadah berbagi ide, program kerja, dan pengalaman antar divisi, sehingga tercipta pertukaran informasi yang bermanfaat. Selain itu, terdapat sesi permainan interaktif yang dirancang untuk mempererat kebersamaan antar peserta, serta kegiatan tambahan berupa tur kampus UIN Sunan Gunung Djati Bandung yang memberikan wawasan tentang lingkungan akademik kampus tersebut. Dengan variasi sesi yang menarik dan penuh nilai, Make Connection berhasil memberikan manfaat yang signifikan, baik dalam pengembangan organisasi maupun penguatan hubungan personal antar pengurus."},{"type":"paragraph","text":"<strong>Penutup </strong>"},{"type":"paragraph","text":"Melalui kegiatan Make Connection, para pengurus Himpunan Mahasiswa Sistem Informasi Unsika memperoleh banyak wawasan baru, pengalaman berharga, serta hubungan yang lebih erat dengan himpunan dari kampus lain. Setiap rangkaian acara dirancang untuk memperkuat kerja sama, menambah pengetahuan keorganisasian, serta membuka peluang kolaborasi di masa mendatang."},{"type":"paragraph","text":"Diharapkan kegiatan ini dapat menjadi langkah awal untuk membangun jejaring yang lebih luas antar Himatif UIN SGD Bandung, sekaligus menjadi inspirasi bagi kegiatan serupa yang lebih inovatif dan berdampak. Make Connection bukan hanya tentang bertukar informasi, tetapi juga tentang menciptakan hubungan yang berkelanjutan dalam semangat kebersamaan dan pengembangan organisasi."}]'::jsonb, 'HIMSIKA'),
(14, 'Seminar Workshop Education Fair 2025 “From Data to Intelligence: Practical Machine Learning & Deep Learning Applications”', 'Berita', '29 Juli 2025', '2025-07-29', '', 'Seminar Workshop Education Fair 2025 “From Data to Intelligence: Practical Machine Learning & Deep Learning Applications”', '[{"type":"gallery","images":[{"src":"","alt":"IMG_8455"},{"src":"","alt":"IMG_8496"},{"src":"","alt":"IMG_8522"},{"src":"","alt":"IMG_8572"},{"src":"","alt":"IMG_8734"},{"src":"","alt":"IMG_9088"},{"src":"","alt":"IMG_9124"},{"src":"","alt":"IMG_9131"},{"src":"","alt":"Sesi Seminar (7)"},{"src":"","alt":"Sesi Workshop (6)"}]},{"type":"paragraph","text":"<b>Seminar Workshop Education Fair 2025 <br /></b><em><strong>“From Data to Intelligence: Practical Machine Learning & Deep Learning Applications”</strong></em>"},{"type":"paragraph","text":"Pada hari Minggu, 4 Mei 2025, Himpunan Mahasiswa Sistem Informasi Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang telah sukses melaksanakan salah satu program kerja besar dalam rangkaian Education Fair 2025, yaitu Seminar Workshop Nasional. Kegiatan ini mengusung tema “From Data to Intelligence: Practical Machine Learning & Deep Learning Applications” dan diselenggarakan di Aula Husni Hamid, Karawang, serta dapat diikuti secara daring dan luring untuk sesi seminar."},{"type":"paragraph","text":"<strong>Tujuan dan Bentuk Kegiatan</strong>"},{"type":"paragraph","text":"Seminar Workshop Nasional ini bertujuan untuk memperluas wawasan dan keterampilan praktis mahasiswa serta masyarakat umum di bidang Machine Learning (ML) dan Deep Learning (DL). Kegiatan ini diharapkan dapat menjadi sarana penguatan kompetensi peserta dalam menghadapi era revolusi industri yang semakin didominasi oleh teknologi kecerdasan buatan."},{"type":"paragraph","text":"Kegiatan ini terbagi dalam dua rangkaian acara, yakni seminar dan workshop yang masing-masing menghadirkan pemateri berkompeten di bidangnya. Abdu Halim Wibowo, selaku CEO Haltev IT Learning Center, menjadi pemateri dalam sesi seminar dengan membawakan materi berjudul “How Machine Learning & Deep Learning are Revolutionizing Industries”. Dalam pemaparannya, beliau menjelaskan secara komprehensif tentang bagaimana teknologi Machine Learning dan Deep Learning telah merevolusi berbagai sektor industri, dilengkapi dengan pembahasan mengenai tren, aplikasi, serta tantangan yang dihadapi dalam penerapannya di dunia nyata."},{"type":"paragraph","text":"Sementara itu, sesi workshop dipandu oleh Farhan Abyan Putra, seorang Machine Learning Engineer sekaligus pemateri workshop yang telah menuntaskan program Bangkit Academy by Google, GoTo, Traveloka, dan Dicoding tahun 2024. Workshop ini mengangkat tema “Exploring the World of Artificial Intelligence: How It’s Made and Works”, yang mengajak peserta untuk mengeksplorasi lebih dalam mengenai cara kerja, proses pembuatan, serta penerapan kecerdasan buatan. Workshop dilaksanakan secara luring dengan ketentuan peserta membawa laptop masing-masing untuk menunjang sesi praktik langsung."},{"type":"paragraph","text":"<strong>Rangkaian Acara</strong>"},{"type":"paragraph","text":"Acara dimulai sejak pukul 09.00 WIB dengan sesi seminar yang berlangsung secara hybrid (luring dan daring), dibuka oleh moderator dan ditutup dengan sesi tanya jawab yang berlangsung interaktif karena peserta antusias mengajukan berbagai pertanyaan seputar topik Machine Learning dan Deep Learning. Antusiasme peserta mencerminkan ketertarikan yang tinggi terhadap perkembangan teknologi kecerdasan buatan dalam berbagai sektor industri."},{"type":"paragraph","text":"Setelah istirahat singkat, peserta luring melanjutkan dengan mengikuti workshop yang dipandu oleh Farhan Abyan Putra. Dalam sesi ini, peserta tidak hanya menerima teori namun juga praktik langsung mengenai pengembangan kecerdasan buatan. Suasana workshop berlangsung dinamis dan penuh antusiasme karena peserta diberikan kesempatan untuk mengeksplorasi model dan algoritma AI."},{"type":"paragraph","text":"<strong>Penutup</strong>"},{"type":"paragraph","text":"Seminar Workshop Nasional Education Fair 2025 berjalan dengan lancar dan berhasil mencapai tujuannya sebagai wahana edukasi dan pengembangan keterampilan di bidang teknologi kecerdasan buatan. Kegiatan ini tidak hanya memperkaya pengetahuan peserta tentang Machine Learning dan Deep Learning, tetapi juga menjadi ajang berharga untuk membangun jejaring dengan para profesional di bidang teknologi."},{"type":"paragraph","text":"Antusiasme tinggi dari para peserta menjadi indikasi bahwa kebutuhan akan pemahaman teknologi mutakhir semakin besar, khususnya bagi mahasiswa yang tengah mempersiapkan diri memasuki dunia profesional. Dengan terselenggaranya kegiatan ini, diharapkan peserta yang hadir semakin siap menghadapi tantangan era digital dengan bekal kompetensi yang relevan dan aplikatif. Seminar Workshop Nasional Education Fair 2025 menjadi bukti nyata komitmen Himsika dalam mendukung pengembangan SDM unggul di bidang teknologi informasi."}]'::jsonb, 'HIMSIKA'),
(15, 'REVOIST 4.0 “Spirit Of Fire, Relighting Dreams and Changing the Future”', 'Berita', '31 Desember 2024', '2024-12-31', '', 'REVOIST 4.0“Spirit Of Fire, Relighting Dreams and Changing the Future”', '[{"type":"gallery","images":[{"src":"","alt":"IMG_8727"},{"src":"","alt":"IMG_8041"},{"src":"","alt":"IMG_9700"},{"src":"","alt":"IMG_8987"},{"src":"","alt":"IMG_8002"},{"src":"","alt":"IMG_8709"},{"src":"","alt":"IMG_9144"},{"src":"","alt":"IMG_9656"},{"src":"","alt":"IMG_8641"},{"src":"","alt":"IMG_9200"},{"src":"","alt":"IMG_7969"},{"src":"","alt":"IMG_9192"},{"src":"","alt":"IMG_8681"},{"src":"","alt":"IMG_9707"},{"src":"","alt":"IMG_8717"}]},{"type":"paragraph","text":"<b>REVOIST 4.0<br />“Spirit Of Fire, Relighting Dreams and Changing the Future”</b>"},{"type":"paragraph","text":"Pada tanggal 17 November 2024, HIMSIKA (Himpunan Mahasiswa Sistem Informasi dan Komputer) merayakan Dies Natalis ke-4 dengan acara besar bertajuk REVOIST 4.0. Acara ini mengusung tema “Spirit Of Fire, Relighting Dreams and Changing the Future”, yang mengajak seluruh peserta untuk membangkitkan semangat dan impian dalam dunia Sistem Informasi dan teknologi. Dies Natalis HIMSIKA ke-4 ini bertujuan untuk merayakan perjalanan organisasi HIMSIKA serta menyalakan kembali api semangat untuk terus berinovasi dan memberikan kontribusi positif untuk masa depan. Acara ini akan menjadi momentum istimewa untuk mengenang perjalanan HIMSIKA serta merayakan pencapaian yang telah diraih dalam empat tahun berdirinya organisasi ini."},{"type":"paragraph","text":"Acara Dies Natalis HIMSIKA ke-4 dimulai dengan Opening Ceremony pada pukul 10.00 WIB, diikuti dengan Open Gate pada pukul 14.00 WIB. Semua rangkaian acara akan berlangsung di Sky Garden, Technomart Mall Karawang. Seluruh anggota HIMSIKA dan pengunjung diundang untuk hadir dan meramaikan momen spesial ini."},{"type":"paragraph","text":"<b>Himsika’s Odyssey</b><br />Sebagai bagian dari perayaan Dies Natalis ke-4, HIMSIKA memproduksi video dokumentasi bernama Himsika’s Odyssey. Video ini terdiri dari empat episode yang menceritakan perjalanan HIMSIKA dari awal terbentuk hingga saat ini. Dengan menggali sejarah dan perkembangan organisasi, video ini memberikan gambaran yang mendalam tentang kontribusi HIMSIKA dalam dunia Sistem Informasi."},{"type":"paragraph","text":"<b>Revoist 4.0 Challenge</b><br />Acara ini semakin meriah dengan adanya berbagai kategori nominasi dalam Revoist 4.0 Challenge, yang melibatkan pengunjung dalam berbagai kompetisi seru:<br /><b>1. Best Costume Tonight<br /></b>Nominasi ini diberikan kepada pengunjung yang hadir dengan kostum terbaik, paling unik, dan sesuai dengan tema acara.<br /><b>2. Best Performance</b><br />Penampilan terbaik yang menonjol berdasarkan kriteria teknik, kualitas, dan kreativitas, akan mendapatkan penghargaan.<br /><b>3. Snapvoist Challenge</b><br />Pengunjung dapat berpartisipasi dengan mengunggah keseruan acara melalui Instastory menggunakan template Instagram Revoist 4.0.<br /><b>4. Quizizz Challenge</b><br />Sebuah kuis seputar Revoist 4.0 akan diselenggarakan di Instastory, di mana followers dapat berpartisipasi dan menjawab pertanyaan secepatnya. Pemenang yang menjawab dengan benar dan tercepat diumumkan di akhir acara."},{"type":"paragraph","text":"<b>Dokumentasi dan Photobooth</b><br />Sebagai bentuk dokumentasi acara, REVOIST 4.0 menyediakan Photobooth yang akan dibuka selama 3 jam, dari pukul 16.00 WIB hingga 19.00 WIB. Pengunjung yang telah melakukan registrasi akan menerima kupon dengan QR Code, yang akan mengarah pada hasil foto yang dapat diakses secara online. Kupon ini juga berfungsi sebagai nomor undian untuk Doorprize yang akan dibagikan pada akhir acara. Bagi yang tidak sempat menggunakan Photobooth dalam waktu tersebut, mereka masih dapat berfoto di spot yang disediakan dengan perangkat pribadi."},{"type":"paragraph","text":"<b>Pentas Seni Angkatan</b><br />Sebagai penutup rangkaian acara, Pentas Seni Angkatan akan menampilkan berbagai penampilan menarik dari grup-grup angkatan HIMSIKA. Pada acara ini, akan ada 3 grup dari angkatan 2024, 1 grup dari angkatan 2023, dan 1 grup dari angkatan 2022 yang akan menunjukkan talenta mereka dalam berbagai bentuk pertunjukkan seni mulai dari penampilan band musik, sampai pertunjukkan modern dance."},{"type":"paragraph","text":"<b>Penutup</b><br />Dies Natalis HIMSIKA ke-4 yang bernama REVOIST 4.0 ini menjadi acara yang sangat berkesan, penuh dengan rangkaian kegiatan menarik, kompetisi, dokumentasi, serta pentas seni yang menggambarkan semangat dan perjalanan HIMSIKA. Tidak hanya untuk merayakan 4 tahun eksistensi HIMSIKA, acara ini juga mempererat hubungan antar anggota, memperkenalkan HIMSIKA kepada lebih banyak orang, dan memperkuat jaringan di dunia Sistem Informasi."}]'::jsonb, 'HIMSIKA'),
(16, 'Make Connection 2024: Membangun Koneksi Melalui Komunikasi Efektif,Memperkuat Organisasi Melalui Brainstorming Yang Produktif', 'Berita', '31 Desember 2024', '2024-12-31', '', 'Make Connection 2024', '[{"type":"gallery","images":[{"src":"","alt":"IMG_1095"},{"src":"","alt":"IMG_0538"},{"src":"","alt":"IMG_0882"},{"src":"","alt":"IMG_0776"},{"src":"","alt":"IMG_0754"},{"src":"","alt":"IMG_0708"},{"src":"","alt":"IMG_0573"},{"src":"","alt":"IMG_3034"},{"src":"","alt":"IMG_2931"},{"src":"","alt":"IMG_3022"},{"src":"","alt":"Salinan IMG_2776"},{"src":"","alt":"IMG_2323"},{"src":"","alt":"IMG_2994"},{"src":"","alt":"IMG_2973"},{"src":"","alt":"IMG_2366"}]},{"type":"paragraph","text":"<b>Make Connection 2024</b>"},{"type":"paragraph","text":"Make Connection merupakan program yang bertujuan untuk membangun koneksi melalui komunikasi yang efektif serta memperkuat organisasi melalui brainstorming yang produktif."},{"type":"paragraph","text":"<b>Make Connection 1</b><b> </b>dilaksanakan di Funzone Festive Walk Karawang dengan dihadiri oleh 73 partisipan. Acara ini dirancang untuk mendorong pengurus mencari cara komunikasi yang paling efektif guna menunjang atau memberikan insight baru bagi Himsika, khususnya melalui brainstorming untuk memecahkan berbagai tantangan organisasi. Rangkaian kegiatannya meliputi pemaparan divisi atau departemen dari masing-masing himpunan untuk saling mengenal peran dan tugas masing-masing, forum group discussion antar divisi yang saling berkaitan guna menemukan solusi bersama, serta permainan interaktif untuk meningkatkan bonding dan kekompakan antar peserta."},{"type":"paragraph","text":"<b> Make Connection 2 </b>dilaksanakan di Gedung Labtek V Institut Teknologi Bandung dengan jumlah partisipan sebanyak 76 orang. Selain membahas insight keorganisasian, acara ini juga diharapkan mampu memberikan wawasan akademik yang relevan dengan kebutuhan para peserta, mengingat lokasinya berada di kampus besar dengan fasilitas unggulan. Rangkaian kegiatan dalam Make Connection kedua meliputi pemaparan divisi atau departemen untuk memahami struktur organisasi secara lebih mendalam, forum group discussion untuk berbagi ide dan pengalaman antar divisi, permainan interaktif untuk mempererat kebersamaan peserta, serta tambahan kegiatan berupa kampus tour yang memberikan pengalaman edukatif mengenai lingkungan akademik Institut Teknologi Bandung. Dengan pendekatan yang berbeda di setiap sesi, program ini berhasil memberikan manfaat baik secara organisasi maupun secara personal bagi setiap partisipan."}]'::jsonb, 'HIMSIKA'),
(17, 'Information System Company Tour 2024:“Menjelajahi Dunia Kerja Sistem Informasi: Membuka Gerbang Peluang dan Koneksi”', 'Berita', '31 Desember 2024', '2024-12-31', '', 'Information System Company Tour 2024', '[{"type":"gallery","images":[{"src":"","alt":"IMG_1280"},{"src":"","alt":"IMG_1334"},{"src":"","alt":"IMG_9275"},{"src":"","alt":"IMG_1296"},{"src":"","alt":"IMG_9241"},{"src":"","alt":"IMG_9291"},{"src":"","alt":"IMG_9368"},{"src":"","alt":"IMG_9274"}]},{"type":"paragraph","text":"<b>Information System Company Tour 2024</b>"},{"type":"paragraph","text":"<b>“Menjelajahi Dunia Kerja Sistem Informasi: Membuka Gerbang Peluang dan Koneksi”</b>"},{"type":"paragraph","text":"Pada hari Kamis, 27 Juni 2024, Himpunan Mahasiswa Sistem Informasi Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang sukses menyelenggarakan program kerja terbarunya yang bernama “Information System Company Tour 2024”. Kegiatan yang mengusung tema “Menjelajahi Dunia Kerja Sistem Informasi: Membuka Gerbang Peluang dan Koneksi” ini berlangsung di Indosat Marvelous Xperience Center dan dihadiri oleh peserta yang seluruhnya merupakan pengurus HIMSIKA."},{"type":"paragraph","text":"<b>Tujuan dan Bentuk Kegiatan</b>"},{"type":"paragraph","text":"Information System Company Tour 2024 dirancang untuk memberikan wawasan dan pengalaman nyata kepada pengurus HIMSIKA mengenai implementasi teknologi informasi di dunia kerja. Selain memperluas pengetahuan, kegiatan ini juga bertujuan untuk membangun koneksi dengan para profesional di bidang Sistem Informasi. Peserta diajak untuk mengeksplorasi berbagai teknologi canggih yang diterapkan di Indosat, seperti Augmented Reality/Virtual Reality (AR/VR), komunikasi Machine-to-Machine (M2M), Artificial Intelligence (AI), dan robotika."},{"type":"paragraph","text":"Kegiatan ini juga memberikan kesempatan bagi peserta untuk melihat secara langsung bagaimana teknologi informasi diintegrasikan dalam operasi bisnis sehari-hari, sehingga diharapkan dapat menjadi inspirasi dalam pengembangan karier mereka di masa depan."},{"type":"paragraph","text":"<b>Rangkaian Acara</b>"},{"type":"paragraph","text":"Acara dimulai dengan sambutan dari perwakilan Indosat yang memperkenalkan visi perusahaan dalam mendukung inovasi teknologi di Indonesia. Peserta kemudian diajak tur keliling fasilitas, termasuk Indosat Marvelous Xperience Center, yang menampilkan implementasi nyata teknologi masa depan."},{"type":"paragraph","text":"Diskusi interaktif dengan profesional di bidang teknologi juga menjadi salah satu bagian menarik dari kegiatan ini. Para peserta aktif bertanya mengenai tantangan, peluang, serta peran Sistem Informasi dalam menghadapi transformasi digital."},{"type":"paragraph","text":"<b>Penutup</b>"},{"type":"paragraph","text":"Information System Company Tour 2024 berhasil mencapai tujuan utamanya, yaitu membuka wawasan pengurus HIMSIKA mengenai dunia kerja di bidang Sistem Informasi. Para peserta mendapatkan pemahaman yang lebih mendalam tentang bagaimana teknologi informasi diimplementasikan dalam industri, serta menjalin koneksi baru yang dapat mendukung karier mereka di masa depan."},{"type":"paragraph","text":"Program ini diharapkan menjadi inspirasi bagi kegiatan serupa di masa mendatang, yang dapat terus mempererat hubungan antara HIMSIKA dengan dunia profesional. Dengan pengetahuan dan wawasan yang telah diperoleh, HIMSIKA optimis dapat meningkatkan peran aktif anggotanya dalam menghadapi tantangan era digital."},{"type":"paragraph","text":"Information System Company Tour 2024 bukan hanya sebuah kunjungan, melainkan sebuah perjalanan menuju pemahaman yang lebih baik akan peluang dan potensi di dunia Sistem Informasi."}]'::jsonb, 'HIMSIKA'),
(18, 'Information System Gathering 2024 “Simplicity in Leadership, Togetherness, Solidarity, and Kinship”', 'Berita', '29 November 2024', '2024-11-29', '', 'Information System Gathering 2024', '[{"type":"gallery","images":[{"src":"","alt":"IMG_4452"},{"src":"","alt":"IMG_8870"},{"src":"","alt":"IMG_8943"},{"src":"","alt":"IMMG (69)"},{"src":"","alt":"IMMG (328)"},{"src":"","alt":"IMG_0085"},{"src":"","alt":"IMMG (97)"},{"src":"","alt":"IMMG (103)"},{"src":"","alt":"IMMG (198)"},{"src":"","alt":"IMG_4206"},{"src":"","alt":"IMMG (92)"},{"src":"","alt":"IMG_3977"},{"src":"","alt":"IMG_4205"},{"src":"","alt":"IMMG (65)"},{"src":"","alt":"IMG_4112"},{"src":"","alt":"IMMG (79)"},{"src":"","alt":"_MG_8811"},{"src":"","alt":"IMG_9 (100)"},{"src":"","alt":"_MG_8978"},{"src":"","alt":"IMG (90)"},{"src":"","alt":"IMG_0099"},{"src":"","alt":"IMG_0208"}]},{"type":"paragraph","text":"<strong>I</strong><b>nformation System Gathering 2024</b>"},{"type":"paragraph","text":"<b><br />“</b>Simplicity in Leadership, Togetherness, Solidarity, and Kinship”"},{"type":"paragraph","text":"Sebagai bagian dari upaya kaderisasi, Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang, menyelenggarakan kegiatan Information System Gathering 2024 yang dilaksanakan pada tanggal 12-13 Oktober 2024, bertempat di Bumi Perkemahan Karang Kitri, Desa Karang Mulya, Kecamatan Bojongmangu, Kabupaten Bekasi, Jawa Barat untuk memberikan kesempatan kepada mahasiswa baru Program Studi Sistem Informasi untuk mempererat hubungan antar sesama dan mempersiapkan diri dalam menghadapi dunia perkuliahan serta dunia kerja. Sebagai salah satu tahapan dalam kaderisasi, kegiatan ini diharapkan dapat menciptakan rasa kebersamaan yang kuat di antara mahasiswa baru dan membekali mereka dengan pengetahuan yang bermanfaat untuk masa depan mereka di dunia akademik maupun profesional."},{"type":"paragraph","text":"<br />Kegiatan ini mengusung tema “Simplicity in Leadership, Togetherness, Solidarity, and Kinship” yang menggambarkan pentingnya kepemimpinan, serta nilai-nilai kebersamaan, solidaritas, dan persaudaraan di dalam diri mahasiswa. Dengan tema ini, diharapkan mahasiswa baru dapat membangun jiwa kepemimpinan yang kuat dan saling mendukung dalam perjalanan akademik mereka. Selain itu, kegiatan ini bertujuan untuk memperkenalkan mahasiswa baru pada berbagai konsep dan perkembangan di dunia Sistem Informasi yang relevan dengan tantangan masa depan."},{"type":"paragraph","text":"Bentuk Kegiatan<br />Dalam kegiatan ini, terdapat berbagai sesi materi yang bermanfaat, seperti materi pertama yang mengangkat tema “Technology Development in Information System to Enhance Local UMKM” yang dibawakan oleh Farhan Abyan Putra Karim. Materi ini akan memberikan wawasan mengenai bagaimana perkembangan teknologi informasi dapat meningkatkan daya saing UMKM lokal. Selain itu, kegiatan ini juga menyajikan talkshow dengan tema “Langkah awal memulai karier yang baik dan sesuai dengan ranah Sistem Informasi agar sukses menghadapi Era Society 5.0”, yang menghadirkan Ganes Wisnu Cahya Bagaskara dan Kevin Zamzami sebagai narasumber untuk berbagi pengalaman dan tips memulai karir di dunia Sistem Informasi. Materi kedua, yaitu “Business Model Canvas (BMC) & Dashboard Analitik”, yang disampaikan oleh Inez Zahra, memberikan pengetahuan mengenai bagaimana Business Model Canvas dan dashboard analitik dapat digunakan untuk meningkatkan efektivitas bisnis di era digital ini."},{"type":"paragraph","text":"<br />Selain pemaparan materi, acara ini juga melibatkan kegiatan penting lainnya, seperti pemilihan Ketua Angkatan Mahasiswa Sistem Informasi angkatan 2024, pengukuhan mahasiswa baru, serta serangkaian kegiatan pengakraban yang bertujuan mempererat tali persaudaraan antar mahasiswa, seperti pentas seni dan permainan yang menyenangkan. Semua rangkaian acara ini dirancang untuk menciptakan suasana yang menyenangkan sekaligus mendidik, agar mahasiswa baru dapat merasakan pengalaman yang berkesan dalam proses kaderisasi mereka.<br />Dengan adanya kegiatan ini, diharapkan mahasiswa baru dapat mengembangkan potensi mereka dan mempersiapkan diri untuk menempuh perjalanan akademik serta memasuki dunia kerja yang penuh tantangan."}]'::jsonb, 'HIMSIKA'),
(19, 'LKMM Pra-Dasar 2024 “Membentuk Mahasiswa Unggul dengan Jiwa Kepemimpinan yang Berkarakter, Berintelektual, Inovatif, dan Kolaboratif”', 'Berita', '29 November 2024', '2024-11-29', '', 'LKMM Pra-Dasar 2024', '[{"type":"gallery","images":[{"src":"","alt":"_MG_0162"},{"src":"","alt":"_MG_0166"},{"src":"","alt":"2"},{"src":"","alt":"IMG_0103"},{"src":"","alt":"IMG_1383"},{"src":"","alt":"IMG_0074"},{"src":"","alt":"IMG_1319"},{"src":"","alt":"IMG_1386"},{"src":"","alt":"_MG_0126"},{"src":"","alt":"IMG_1287"},{"src":"","alt":"IMG_1420"},{"src":"","alt":"IMG_1445"},{"src":"","alt":"_MG_0169"},{"src":"","alt":"IMG_1285"},{"src":"","alt":"IMG_1290"}]},{"type":"paragraph","text":"<strong>LKMM Pra-Dasar 2024</strong>"},{"type":"paragraph","text":"“Membentuk Mahasiswa Unggul dengan Jiwa Kepemimpinan yang Berkarakter, Berintelektual, Inovatif, dan Kolaboratif”"},{"type":"paragraph","text":"LKMM (Latihan Kepemimpinan dan Manajemen Mahasiswa) Pra-Dasar 2024 telah sukses dilaksanakan pada Kamis, 22 Agustus 2024, oleh Himpunan Mahasiswa Sistem Informasi (HIMSIKA) Fakultas Ilmu Komputer Universitas Singaperbangsa Karawang. Kegiatan ini ditujukan untuk mahasiswa baru angkatan 2024. Sebagai bagian dari tahapan kaderisasi, LKMM Pra-Dasar bertujuan untuk membekali mahasiswa dengan keterampilan dasar yang esensial dalam kepemimpinan dan organisasi, sehingga dapat mendukung mereka dalam mengembangkan potensi diri dan beradaptasi dengan dinamika kehidupan kampus serta dunia profesional."},{"type":"paragraph","text":"<br />Dengan tema “Membentuk Mahasiswa Unggul dengan Jiwa Kepemimpinan yang Berkarakter, Berintelektual, Inovatif, dan Kolaboratif” menggambarkan tujuan utama dari LKMM Pra-Dasar 2024, yaitu membangun mahasiswa yang memiliki jiwa kepemimpinan yang tangguh dan siap menghadapi tantangan. Selain itu, kegiatan ini juga berfokus pada pengembangan kemampuan intelektual yang kritis dan inovatif, serta keterampilan kolaboratif yang sangat dibutuhkan di era yang semakin mengedepankan kerja sama tim dan ide-ide kreatif. Dengan demikian, LKMM Pra-Dasar 2024 tidak hanya menjadi bekal bagi mahasiswa untuk sukses di dunia akademik, tetapi juga untuk mempersiapkan mereka menghadapi tantangan dunia kerja yang semakin kompetitif."},{"type":"paragraph","text":"<br />Acara ini berlangsung sepanjang hari, dengan berbagai sesi materi yang dirancang untuk memperkenalkan peserta pada konsep-konsep penting dalam kepemimpinan, komunikasi, dan pengembangan diri. Di antara materi yang disampaikan, terdapat Talkshow tentang “Pengenalan Jurusan Sistem Informasi” yang memberikan wawasan tentang dunia studi yang akan dijalani oleh peserta. Selain itu, terdapat pula pemaparan mengenai “Sifat-Sifat Kepemimpinan dan Pola Pikir Prestatif”, yang bertujuan untuk membentuk pola pikir positif dan mendorong peserta agar mampu menjadi pemimpin yang visioner dan produktif. Materi lainnya mencakup “Pemahaman Diri serta Kemampuan Berkomunikasi dan Kolaboratif”, yang mengajarkan peserta pentingnya memahami diri sendiri serta keterampilan dalam berkomunikasi dan bekerja sama dalam kelompok. Di samping itu, peserta juga diperkenalkan dengan “Permikomnas” (Perhimpunan Mahasiswa Ilmu Komputer Nasional), sebuah organisasi yang bertujuan untuk mengembangkan kualitas mahasiswa ilmu komputer di Indonesia melalui berbagai kegiatan yang bersifat nasional. Materi ini bertujuan memberikan pemahaman kepada peserta tentang peran Permikomnas dalam mendukung pengembangan kompetensi mahasiswa di tingkat nasional."},{"type":"paragraph","text":"<br />Setelah sesi materi, peserta dibagi menjadi 10 kelompok untuk mengikuti Forum Group Discussion (FGD) dengan tema “Pentingnya Literasi Sebagai Landasan Pendidikan dan Pengetahuan Mahasiswa”. Setiap kelompok dibimbing oleh seorang Kakak Pembimbing (Kabing) yang bertugas memberikan arahan dan mendampingi peserta dalam diskusi untuk mendalami topik-topik yang dibahas. Dengan format ini, diharapkan peserta dapat lebih aktif berpartisipasi dan saling berbagi pemahaman serta pengalaman dalam suasana yang lebih informal dan interaktif."},{"type":"paragraph","text":"<br />Setelah sesi materi, peserta dibagi menjadi 10 kelompok untuk mengikuti Forum Group Discussion (FGD) dengan tema “Pentingnya Literasi Sebagai Landasan Pendidikan dan Pengetahuan Mahasiswa”. Setiap kelompok dibimbing oleh seorang Kakak Pembimbing (Kabing) yang bertugas memberikan arahan dan mendampingi peserta dalam diskusi. FGD ini dirancang untuk mendalami topik-topik yang telah dibahas sebelumnya, sekaligus mendorong partisipasi aktif peserta dalam suasana yang lebih informal dan interaktif."},{"type":"paragraph","text":"<br />Tujuan utama dari FGD ini adalah untuk meningkatkan kesadaran mahasiswa terhadap pentingnya literasi sebagai dasar dalam pengembangan pendidikan dan pengetahuan mereka. Literasi tidak hanya berkaitan dengan kemampuan membaca dan menulis, tetapi juga mencakup pemahaman kritis terhadap informasi, pengelolaan pengetahuan, serta penerapan wawasan dalam pengambilan keputusan. Dengan diskusi ini, diharapkan mahasiswa dapat lebih memahami bagaimana literasi berperan penting dalam kehidupan akademik maupun dunia kerja, serta termotivasi untuk terus meningkatkan kemampuan literasi mereka sebagai landasan yang kuat dalam membangun kompetensi diri."},{"type":"paragraph","text":"<br />LKMM Pra-Dasar 2024 menjadi ajang penting bagi mahasiswa baru untuk mengenal lebih dalam tentang dunia organisasi, mengasah keterampilan kepemimpinan, serta membangun karakter yang akan berguna dalam perjalanan mereka sebagai mahasiswa dan pemimpin di masa depan. Melalui kegiatan ini, diharapkan peserta dapat semakin siap untuk berkontribusi dalam kehidupan kampus dan siap menghadapi dunia profesional dengan lebih percaya diri."}]'::jsonb, 'HIMSIKA'),
(20, 'Education Fair : Silogy Expo 2024 – AI  Everywhere: How Artificial Intelligence Changing Our World', 'Berita', '24 Oktober 2024', '2024-10-24', '', 'Silogy Expo – Education Fair 2024', '[{"type":"gallery","images":[{"src":"","alt":"DSC_9208"},{"src":"","alt":"IMG_0265"},{"src":"","alt":"IMG_0330"},{"src":"","alt":"IMG_0222"},{"src":"","alt":"IMG_0270"},{"src":"","alt":"IMG_0215"},{"src":"","alt":"IMG_0637"},{"src":"","alt":"IMG_0305"},{"src":"","alt":"DSC_9304"},{"src":"","alt":"DSC_9238"},{"src":"","alt":"DSC_9233"},{"src":"","alt":"IMG_0486"},{"src":"","alt":"IMG_0119"},{"src":"","alt":"IMG_0179"}]},{"type":"paragraph","text":"<strong>Silogy Expo – Education Fair 2024</strong>"},{"type":"paragraph","text":"Silogy Expo, salah satu acara besar dalam rangkaian Education Fair 2024, diselenggarakan oleh Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang. Acara ini berlangsung pada Sabtu, 10 Agustus 2024, di Techno Mart, Karawang, dan juga tersedia secara daring melalui Zoom Meeting yang keduanya diikuti oleh 550 orang. Expo ini menampilkan beragam pameran inovatif karya mahasiswa sistem informasi Universitas Singaperbangsa Karawang, sekaligus menjadi ajang berbagi ide serta inspirasi di bidang teknologi informasi."},{"type":"paragraph","text":"Silogy Expo, singkatan dari Sistem Informasi Technology Festival and Expo, mencakup beberapa lomba seperti Web Development, UI/UX, dan Desain Grafis. Selain kompetisi, terdapat Talkshow yang mengangkat tema “AI Everywhere: How Artificial Intelligence Changing Our World” dengan tujuan memberikan wawasan mendalam mengenai penerapan kecerdasan buatan (AI) di berbagai sektor industri. Dua pembicara utama dalam Talkshow ini adalah Nina Sulistiyowati, S.T., M.Kom., dan E. Haodudin Nurkifli, S.T., M.Cs., Ph.D., yang keduanya merupakan dosen dari Fakultas Ilmu Komputer (FASILKOM) Universitas Singaperbangsa Karawang."},{"type":"paragraph","text":"Sebelum acara puncak pada 10 Agustus, rangkaian kompetisi Silogy Expo telah dimulai perlombaan “Silogy Expo National Competition 2024” sejak 29 Mei hingga 27 Juli 2024. Perlombaan ini berlangsung secara daring dan melibatkan mahasiswa dari berbagai daerah di Indonesia yang berkompetisi dalam tiga kategori utama: UI/UX, Web Development, dan Desain Grafis. Berikut adalah para tim dan individu yang berhasil meraih prestasi gemilang dalam setiap kategori:"},{"type":"paragraph","text":"Pemenang Lomba Silogy Expo National Competition 2024:"},{"type":"list","ordered":true,"items":["Kategori UI/UX:"]},{"type":"list","ordered":false,"items":["🥇 Juara Pertama: Tim Phoenix Stars","🥈 Juara Kedua: Tim UI Squad","🥉 Juara Ketiga: Tim Tam Girlies","🎖️ Harapan Pertama: Tim Yeartica","🎖️ Harapan Kedua: Tim Powerpuff Boys"]},{"type":"list","ordered":true,"items":["Kategori Web Development:"]},{"type":"list","ordered":false,"items":["🥇 Juara Pertama: Tim Silent Code","🥈 Juara Kedua: Tim Mathlearns","🥉 Juara Ketiga: Angga Sukha Pratama"]},{"type":"list","ordered":true,"items":["Kategori Desain Grafis:"]},{"type":"list","ordered":false,"items":["🥇 Juara Pertama: Tim Three Musketeers","🥈 Juara Kedua: Tim Jurnalistik7","🥉 Juara Ketiga: Nabilah Kultsum","🎖️ Harapan Pertama: Andi Marwah Ramadhani"]},{"type":"paragraph","text":"Pada acara puncak Silogy Expo, selain Talkshow, juga diumumkan pemenang karya pameran terbaik yang telah dihasilkan oleh mahasiswa Sistem Informasi. Pameran ini menampilkan inovasi dalam bidang e-commerce, aplikasi berbasis Augmented Reality, serta berbagai platform teknologi lainnya."},{"type":"paragraph","text":"Pemenang Karya Pameran Terbaik Silogy Expo 2024:"},{"type":"list","ordered":false,"items":["Karya Terbaik 1: Fiza Group – PAKE.IN (Platform Fashion E-Commerce berbasis Augmented Reality dan fitur yang berorientasi pada pengguna)","Karya Terbaik 2: Tim Farchar – TernakIn (Platform jual beli daging online)","Karya Terbaik 3: M. Rafi Ilmuna – Mengukir Jejak Digital: Etika dalam Bermedia Sosial (Poster ilmiah)"]},{"type":"paragraph","text":"Silogy Expo tidak hanya menjadi ajang kompetisi, tetapi juga sebagai tempat mahasiswa untuk menampilkan ide-ide kreatif mereka dalam memanfaatkan teknologi terbaru. Expo ini diharapkan dapat menginspirasi peserta dan pengunjung untuk terus berinovasi di era digital. Silogy Expo 2024 menegaskan pentingnya inovasi teknologi di era digital, serta memberikan ruang bagi mahasiswa dan pelaku industri untuk saling berbagi ide dan solusi teknologi yang relevan dengan kebutuhan masa kini."}]'::jsonb, 'HIMSIKA'),
(21, 'Education Fair : Seminar Workshop Nasional 2024 – Inovasi Blockchain Dalam Revolusi Society 5.0', 'Berita', '24 Oktober 2024', '2024-10-24', '', 'Seminar Workshop Nasional – Education Fair 2024', '[{"type":"gallery","images":[{"src":"","alt":"IMG_0032"},{"src":"","alt":"IMG_6327"},{"src":"","alt":"IMG_0042"},{"src":"","alt":"IMG_0146"},{"src":"","alt":"IMG_9982"},{"src":"","alt":"IMG_6330"},{"src":"","alt":"IMG_9522"},{"src":"","alt":"IMG_9874"},{"src":"","alt":"IMG_9532"},{"src":"","alt":"Screenshot (189)"},{"src":"","alt":"_MG_8951 (1)"},{"src":"","alt":"DSC_0078"},{"src":"","alt":"DSC_0099"},{"src":"","alt":"IMG_0014"},{"src":"","alt":"IMG_0173"}]},{"type":"paragraph","text":"<strong>Seminar Workshop Nasional – Education Fair 2024</strong>"},{"type":"paragraph","text":"Himpunan Mahasiswa Sistem Informasi Universitas Singaperbangsa Karawang kembali menghadirkan program tahunan yang dinantikan, yakni<b> <i>Education Fair 2024</i></b>. Salah satu acara unggulan dalam rangkaian kegiatan ini adalah Seminar Workshop Nasional, yang diselenggarakan pada Sabtu, 18 Mei 2024, di aula Husni Hamid, Pemda Karawang yang diikuti oleh 1500 peserta, baik secara daring maupun luring."},{"type":"paragraph","text":"Dengan tema “<i><b>Inovasi Blockchain dalam Revolusi Society 5.0</b></i>“, seminar ini mengeksplorasi bagaimana teknologi blockchain dapat memberikan dampak signifikan terhadap berbagai sektor industri, terutama dalam era transformasi digital yang pesat. Seminar ini dibuka untuk seluruh mahasiswa Indonesia serta masyarakat umum yang ingin memperdalam pengetahuan tentang blockchain, sekaligus memperkaya wawasan seputar <b>keamanan teknologi blockchain dalam bisnis digital</b>."},{"type":"paragraph","text":"Seminar ini menghadirkan dua pemateri ahli, yaitu Erikman Pardamean, yang merupakan Program Director dari ISACA Indonesia sekaligus Technology Partner di RSM Indonesia, dan Naufal Ahmad Fadillah, seorang pengembang perangkat lunak yang juga merupakan penggiat Web3. Selain diskusi mendalam, peserta juga mendapatkan kesempatan untuk mengikuti pelatihan mengenai blockchain berbasis smart contract pada platform Ethereum dengan Ganache, yang memberikan pemahaman praktis tentang implementasi teknologi ini di dunia nyata."},{"type":"paragraph","text":"Seminar ini diharapkan menjadi platform bagi mahasiswa dan masyarakat umum untuk memahami lebih dalam tentang potensi besar teknologi blockchain, sekaligus mengasah kemampuan mereka dalam memanfaatkan teknologi ini dalam kehidupan sehari-hari maupun masa depan."}]'::jsonb, 'HIMSIKA'),
(22, 'REVOIST 3.0 : “Taking Responsibility for the Great Opportunity”', 'Berita', '16 Desember 2023', '2023-12-16', '', 'Dies Natalis HIMSIKA atau REVOIST3.0 adalah program kerja yang memperingati hari jadi HIMSIKA yang ke-3. Ini merupakan suatu tolak ukur bagi himpunan dalam menjalani 3 tahun kepengurusan, maka dengan itu harapan…', '[{"type":"gallery","images":[{"src":"","alt":"IMG_6182"},{"src":"","alt":"IMG_6160"},{"src":"","alt":"IMG_6136"},{"src":"","alt":"DSCF1112"},{"src":"","alt":"DSC_0345"},{"src":"","alt":"_MG_0403"},{"src":"","alt":"_MG_0381 (1)"},{"src":"","alt":"_MG_0096"},{"src":"","alt":"Salinan _MG_0500"},{"src":"","alt":"Salinan _MG_0501"},{"src":"","alt":"Salinan DSC_0067"},{"src":"","alt":"Salinan DSCF1119"},{"src":"","alt":"Salinan DSCF1352"},{"src":"","alt":"IMG_9398"},{"src":"","alt":"Salinan IMG_3682"}]},{"type":"paragraph","text":"Dies Natalis HIMSIKA atau REVOIST3.0 adalah program kerja yang memperingati hari jadi HIMSIKA yang ke-3. Ini merupakan suatu tolak ukur bagi himpunan dalam menjalani 3 tahun kepengurusan, maka dengan itu harapan kedepannya himsika menjadi lebih berkembang dan menjadi organisasi terdepan dalam mewujudkan visi misi program studi Sistem Informasi UNSIKA"},{"type":"paragraph","text":"REVOIST3.0 berlangsung dengan nuansa Nusantara demi mempertahankan kebudayaan bangsa di era teknologi ini. Dengan berbagai rangkaian seperti penampilan kelas, pagelaran budaya, hingga perform guest star. Diharapkan bisa menjadi sebuah momentum bagi mahasiswa Sistem Informasi dalam menjalin kekeluargaan antara anggota dan pengurus HIMSIKA"},{"type":"gallery","images":[{"src":"","alt":"DSC_9208"},{"src":"","alt":"IMG_0265"},{"src":"","alt":"IMG_0330"},{"src":"","alt":"IMG_0222"},{"src":"","alt":"IMG_0270"},{"src":"","alt":"IMG_0215"},{"src":"","alt":"IMG_0637"},{"src":"","alt":"IMG_0305"},{"src":"","alt":"DSC_9304"},{"src":"","alt":"DSC_9238"},{"src":"","alt":"DSC_9233"},{"src":"","alt":"IMG_0486"},{"src":"","alt":"IMG_0119"},{"src":"","alt"