-- ------------------------------------------------------------
-- BAGIAN 1: PEMBUATAN TABEL (DDL) & KEAMANAN (RLS)
-- Aman dijalankan berulang kali (tidak akan menimpa tabel yang ada)
-- ------------------------------------------------------------

-- 1. TABEL LOMBA & BEASISWA
CREATE TABLE IF NOT EXISTS public.lomba (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL,
    organizer TEXT NOT NULL,
    description TEXT,
    deadline_pendaftaran TEXT,
    deadline_pengumpulan TEXT,
    benefit TEXT,
    categories JSONB DEFAULT '[]'::jsonb,
    deadline_timestamp BIGINT,
    registration_url TEXT,
    guidebook_url TEXT,
    instagram_url TEXT,
    contacts JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. TABEL ARTIKEL & BERITA
CREATE TABLE IF NOT EXISTS public.artikel (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL,
    category TEXT NOT NULL DEFAULT 'Berita',
    date TEXT,
    datetime TEXT,
    image TEXT,
    excerpt TEXT,
    content JSONB,
    author TEXT DEFAULT 'HIMSIKA',
    is_hot BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT NOW()
);
ALTER TABLE public.artikel ADD COLUMN IF NOT EXISTS is_hot BOOLEAN DEFAULT false;

-- 3. TABEL PRESTASI MAHASISWA
CREATE TABLE IF NOT EXISTS public.prestasi (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    peringkat TEXT NOT NULL,
    judul TEXT NOT NULL,
    pemenang JSONB DEFAULT '[]'::jsonb,
    gambar TEXT,
    instagram_url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. TABEL GALERI KEGIATAN
CREATE TABLE IF NOT EXISTS public.galeri (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    album TEXT NOT NULL,
    album_slug TEXT,
    foto TEXT NOT NULL,
    caption TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. TABEL PENGURUS & STRUKTUR ORGANISASI (PROFIL)
CREATE TABLE IF NOT EXISTS public.pengurus (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nama TEXT NOT NULL,
    jabatan TEXT NOT NULL,
    kelompok TEXT NOT NULL DEFAULT 'bph',
    foto TEXT,
    instagram TEXT,
    linkedin TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- AKTIFKAN ROW LEVEL SECURITY (RLS)
ALTER TABLE public.lomba ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.artikel ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.prestasi ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.galeri ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pengurus ENABLE ROW LEVEL SECURITY;

-- POLICIES
DROP POLICY IF EXISTS "Public can view lomba" ON public.lomba;
CREATE POLICY "Public can view lomba" ON public.lomba FOR SELECT USING (true);
DROP POLICY IF EXISTS "Authenticated can modify lomba" ON public.lomba;
CREATE POLICY "Authenticated can modify lomba" ON public.lomba FOR ALL TO authenticated USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public can view artikel" ON public.artikel;
CREATE POLICY "Public can view artikel" ON public.artikel FOR SELECT USING (true);
DROP POLICY IF EXISTS "Authenticated can modify artikel" ON public.artikel;
CREATE POLICY "Authenticated can modify artikel" ON public.artikel FOR ALL TO authenticated USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public can view prestasi" ON public.prestasi;
CREATE POLICY "Public can view prestasi" ON public.prestasi FOR SELECT USING (true);
DROP POLICY IF EXISTS "Authenticated can modify prestasi" ON public.prestasi;
CREATE POLICY "Authenticated can modify prestasi" ON public.prestasi FOR ALL TO authenticated USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public can view galeri" ON public.galeri;
CREATE POLICY "Public can view galeri" ON public.galeri FOR SELECT USING (true);
DROP POLICY IF EXISTS "Authenticated can modify galeri" ON public.galeri;
CREATE POLICY "Authenticated can modify galeri" ON public.galeri FOR ALL TO authenticated USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Public can view pengurus" ON public.pengurus;
CREATE POLICY "Public can view pengurus" ON public.pengurus FOR SELECT USING (true);
DROP POLICY IF EXISTS "Authenticated can modify pengurus" ON public.pengurus;
CREATE POLICY "Authenticated can modify pengurus" ON public.pengurus FOR ALL TO authenticated USING (true) WITH CHECK (true);

-- 6. STORAGE BUCKET UNTUK ASSET GAMBAR (himsika-assets)
VALUES ('himsika-assets', 'himsika-assets', true)
ON CONFLICT (id) DO UPDATE SET public = true;

DROP POLICY IF EXISTS "Public can view himsika-assets" ON storage.objects;
CREATE POLICY "Public can view himsika-assets" ON storage.objects FOR SELECT USING (bucket_id = 'himsika-assets');

DROP POLICY IF EXISTS "Public can upload himsika-assets" ON storage.objects;
CREATE POLICY "Public can upload himsika-assets" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'himsika-assets');

DROP POLICY IF EXISTS "Public can update himsika-assets" ON storage.objects;
CREATE POLICY "Public can update himsika-assets" ON storage.objects FOR UPDATE USING (bucket_id = 'himsika-assets');

DROP POLICY IF EXISTS "Public can delete himsika-assets" ON storage.objects;
CREATE POLICY "Public can delete himsika-assets" ON storage.objects FOR DELETE USING (bucket_id = 'himsika-assets');

-- ------------------------------------------------------------
-- BAGIAN 2: MIGRASI DATA LAMA (SEEDING)
-- ------------------------------------------------------------

-- A. DATA PRESTASI MAHASISWA (9 Data)
DELETE FROM public.prestasi;

-- B. DATA PENGURUS & STRUKTUR ORGANISASI (37 Pengurus)
DELETE FROM public.pengurus;

-- C. DATA GALERI KEGIATAN (47 Foto)
DELETE FROM public.galeri;

-- D. DATA ARTIKEL & BERITA (33 Artikel)
DELETE FROM public.artikel;

-- ------------------------------------------------------------
-- BAGIAN 3: KALIBRASI SEQUENCE IDENTITY COUNTER
-- Memastikan penambahan data baru di masa depan memiliki ID berlanjut
-- ------------------------------------------------------------
SELECT setval(pg_get_serial_sequence('public.prestasi', 'id'), COALESCE((SELECT MAX(id) FROM public.prestasi), 1));
SELECT setval(pg_get_serial_sequence('public.pengurus', 'id'), COALESCE((SELECT MAX(id) FROM public.pengurus), 1));
SELECT setval(pg_get_serial_sequence('public.galeri', 'id'), COALESCE((SELECT MAX(id) FROM public.galeri), 1));
SELECT setval(pg_get_serial_sequence('public.artikel', 'id'), COALESCE((SELECT MAX(id) FROM public.artikel), 1));

-- SELESAI
